(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["video"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-scalable-diffusion-models-with-trans-2022"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-1\">一 · 开场：一个 512×512 在线出图服务的午夜告警</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-2\">二 · 旧方案：U-Net 主干的推理代价结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-3\">三 · 为什么非改不可：三个必须同时满足的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-4\">四 · DiT 的替换：patchify、adaLN-Zero 与固定步数循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-5\">五 · 缩放关系作为容量规划工具，以及它的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-6\">六 · 落在具体机制上：token 数是唯一需要盯住的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-7\">七 · 从“一次前向”到“一条请求”：DiT 推理负载的四元组</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-8\">八 · 输入长度分布：patch 尺寸是隐式的负载旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-9\">九 · 并发与批大小：摊薄权重读取与激活线性上升的对冲</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-10\">十 · SLO 与长尾：固定步数循环下的时延构成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-11\">十一 · 方案反过来限制负载：容量规划中的闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-12\">十二 · 负载画像：token 序列长度如何反过来定义 DiT 推理方案的可行域</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-13\">十三 · 从 Gflops 到 kernel：DiT 前向的算子序列与精度落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-14\">十四 · 数据类型分层：FP16/BF16、FP8、NVFP4 在扩散采样中的分工</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-15\">十五 · 累加精度与误差传播：为什么 MMA 的累加器不能跟着降</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-16\">十六 · Blackwell 特性映射：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-17\">十七 · kernel 融合与数值稳定性的交界：adaLN、softmax 与残差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-18\">十八 · 精度方案与容量规划的耦合：从 token 数反推可行配置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-19\">十九 · 精度下探的边界：DiT 在 Blackwell 上量化到哪一步会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-20\">二十 · 显存账本的三条主线：权重、激活、跨步缓存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-21\">二十一 · 分页与分块：把 S² 注意力拆成可管理的块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-22\">二十二 · 压缩与复用：精度、跨步、条件三条路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-23\">二十三 · 卸载：把哪本账挪出 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-24\">二十四 · 带宽瓶颈在哪：HBM3e 容量与带宽的复算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-25\">二十五 · 一个可复算的显存预算流程</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-26\">二十六 · DiT 显存账本的失效边界：token 平方项与固定步数循环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-27\">二十七 · 从“固定步数循环”到可调度请求</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-28\">二十八 · Chunked prefill：把长序列的首步切开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-29\">二十九 · 优先级与抢占：尾延迟从哪里来</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-30\">三十 · 分离式预填/解码：把首步与后续步分开</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-31\">三十一 · 时延与吞吐的联合规划</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-32\">三十二 · 调度层的可观测项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-33\">三十三 · 从单卡到多卡：DiT 的切分维度与通信原语</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-34\">三十四 · NVLink 5 与 NVSwitch：把 All-Reduce 压进交换结构</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-35\">三十五 · All-to-All 与 EP：MoE 化 FFN 的 token 路由代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-36\">三十六 · PP 与 DP：流水气泡与权重广播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-37\">三十七 · NIXL 传输与分离式部署：预填/解码拆分的搬运账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-38\">三十八 · 瓶颈判据：什么时候通信压过计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-39\">三十九 · 精度塌陷：从“能跑”到“跑对”的断层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-40\">四十 · OOM：token平方项与批大小的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-41\">四十一 · 批抖动：摊薄收益被激活增长吃掉</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-42\">四十二 · 尾延迟：固定步数循环里的长尾</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-43\">四十三 · 静默降级：没有报错的劣化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-44\">四十四 · 失效边界：当 token 平方项压过 Gflops 线性项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-45\">四十五 · 把“Gflops”当作唯一横轴时，口径就已经错了</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-46\">四十六 · 硬件档位与“未给出”的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-47\">四十七 · batch、并发与步数三者的耦合口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-48\">四十八 · 哪些提升不可比：四条判定线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-49\">四十九 · 从论文表格到容量规划的最小读法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-50\">五十 · 当缩放曲线撞上注意力平方：DiT 基准口径的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-51\">五十一 · 从图像DiT迁到视频DiT：序列维度的代价重估</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-52\">五十二 · 迁到非Transformer骨干：可分析性的丧失</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-53\">五十三 · 迁到自回归与流式生成：缓存语义不成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-54\">五十四 · 精度迁移的边界：注意力数值稳定性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-55\">五十五 · 规模上限：token平方与步数线性的双重夹击</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-56\">五十六 · 迁移判断清单：什么能搬、什么必须重做</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-scalable-diffusion-models-with-trans-2022-sec-57\">五十七 · 迁移到长视频与高分辨率时的失效边界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:537px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 537.4 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"455.4\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">VAE编码：把视频/图像帧压到潜空间，降低token数与后续注意力代价。</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"455.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">patchify：按patch尺寸切分潜特征并线性投影为token序列…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"455.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">条件注入：时间步与类别经adaLN-Zero生成逐块scale/shi…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"455.4\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">Transformer块堆叠：全局自注意力与MLP交替，激活显存随to…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"455.4\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">unpatchify与VAE解码：线性层还原patch并解码为像素，解…</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-1\">一 · 开场：一个 512×512 在线出图服务的午夜告警</h3>\n<p>凌晨两点，一个面向设计师的在线图像生成服务触发容量告警：P99 延迟从 1.8 秒跳到 6 秒以上，GPU 显存水位在批大小调到 8 时直接撞上单卡上限，调度器开始拒绝新请求。值班工程师打开 profiling 面板，看到的是一张典型的 U-Net 扩散推理火焰图：编码器下采样堆叠、中间块、解码器上采样堆叠，中间穿插着大量跳连张量；每个去噪步都要把这套卷积主干完整走一遍，采样 50 步就是 50 次完整前向。更麻烦的是，显存峰值并不出现在权重上，而是出现在跳连保留的中间激活上——为了把编码器特征拼回解码器，这些激活必须跨越整个主干存活，批大小每加一档，峰值就抬一截。工程师想做的三件事——把批调大摊薄权重读取、把精度降到 FP8 省带宽、把主干按层切到多卡——在 U-Net 上都缺少一个统一的度量尺度：卷积层的形状随分辨率变化，跳连让切分点难以对齐，算子融合的边界随下采样比例漂移。</p>\n<p>这就是《Scalable Diffusion Models with Transformers》要回答的问题现场。它不是一篇“换个骨干试试”的工程随笔，而是把扩散去噪网络改写成纯 Transformer（DiT），让推理栈第一次可以用 Transformer 的规则去度量：算子序列固定、注意力形状由 token 数决定、激活规模可解析估算。对 Blackwell 上的推理部署而言，这件事的意义不在于骨干叫什么名字，而在于它把一个“形状随分辨率漂移、切分点不可预测”的推理对象，换成了一个“序列长度与层数显式参数化、代价可线性估算”的推理对象。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-2\">二 · 旧方案：U-Net 主干的推理代价结构</h3>\n<p>在 DiT 之前，扩散推理栈的主流做法是以 U-Net 为去噪骨干。它的结构是编码器逐级下采样、解码器逐级上采样，同级特征通过跳连拼接。这套结构在训练上是有效的归纳偏置，但在推理系统里制造了三类具体代价。</p>\n<p>第一类是显存代价的不可压缩性。跳连张量必须在主干前向期间保持存活，其大小由最高分辨率的特征图决定；批大小增加时，这部分激活随批线性增长，且无法像权重那样被多卡摊薄。第二类是算子序列的不规则性。卷积核尺寸、通道数、分辨率在每一级都不同，算子融合的可行边界随层级变化，图优化器很难做跨层的统一规划；相比之下，Transformer 块的形状在同一模型内基本一致，融合与切分的规则可以复用。第三类是并行切分的对齐困难。按层切分时，跳连会跨切分点，引入额外的通信与同步；按空间切分时，下采样比例又让各卡的张量形状不一致。这三类代价叠加的结果是：推理栈的容量规划只能靠实测扫参，无法从模型参数直接推出显存上限与吞吐上界。</p>\n<p>用公式表述这种不可预测性：设第 $l$ 级特征图的空间尺寸为 $H_l\\times W_l$、通道为 $C_l$、批大小为 $B$，则跳连保留的激活规模近似为</p>\n<div class=\"formula\">$$M_{\\text{skip}}\\approx B\\sum_{l\\in\\text{skip}} H_l W_l C_l \\cdot s$$</div>\n<p>其中 $s$ 为每元素字节数。这个求和跨越多个不同形状的层级，无法用一个统一的 token 数来参数化，因此当分辨率或批大小变化时，显存峰值只能重新测量。一个具体例子：同一套 U-Net 在 256×256 与 512×512 两种分辨率下服务，工程师无法用前者的实测数据外推后者的批大小上限，只能各自扫一遍；而每次扫参都占用生产卡时，容量规划变成经验活。</p>\n<p>延迟侧同样如此。每步去噪都要完整走一遍编码器—中间块—解码器，步数增加时延迟线性累积，这一点与骨干无关；但 U-Net 的算子多样性使得单步内的 kernel launch 次数偏多，在 Blackwell 这种以 tcgen05 与 TMEM 为大矩阵运算优化的架构上，碎片化的卷积与小算子难以吃满张量核心，单步的有效算力利用率被结构性地压低。吞吐侧，批处理能摊薄权重读取，但跳连激活随批线性上升，显存与吞吐的折中点同样只能实测。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-3\">三 · 为什么非改不可：三个必须同时满足的约束</h3>\n<p>把问题拆开看，旧方案在三个约束上同时吃紧，而这三个约束恰好是推理部署的硬边界。</p>\n<ul>\n<li><b>精度量化的可分析性。</b>在 Blackwell 上做 NVFP4/FP8 推理，前提是能说清楚哪些张量的数值范围稳定、哪些层对量化误差敏感。U-Net 的跳连拼接把不同层级的特征混在一个张量里，量化粒度被迫粗化；而 Transformer 块的残差流与注意力激活边界清晰，量化点的选择可以按块统一规划。论文没有给出量化实验，但它提供的骨干形态让“按块量化、按注意力形状评估数值稳定性”成为可操作的路径。</li>\n<li><b>激活缓存与跨步复用的可行性。</b>扩散采样是固定步数循环，跨步之间存在可利用的冗余。要复用激活，前提是激活的形状与语义在步与步之间对齐。U-Net 的多级特征图在步间形状一致但语义随层级纠缠；DiT 的 token 序列在步间完全同形，条件嵌入经 adaLN-Zero 逐块注入，缓存复用的对象可以被明确界定为“同形激活张量”。这是后续缓存类工作能在 Transformer 骨干上成立的结构前提。</li>\n<li><b>并行切分的规则化。</b>全局注意力可按序列维切分，切分后每卡的注意力矩阵形状可预测，通信代价可估算；MLP 按隐藏维切分，规则同样统一。U-Net 做不到这一点，因为切分点两侧的张量形状不对称。</li>\n</ul>\n<p>代价上，这三条约束指向同一个工程判断：推理栈需要一个“形状由少数几个显式参数决定”的骨干。DiT 的参数就是层数 $N$、宽度 $d$、patch 尺寸与分辨率，token 数 $L$ 由后两者决定，于是单步代价可以写成</p>\n<div class=\"formula\">$$\\text{Gflops}\\approx k\\cdot N\\cdot d^2\\cdot L,\\qquad M_{\\text{attn}}\\approx B\\cdot h\\cdot L^2\\cdot s$$</div>\n<p>其中 $h$ 为注意力头数。第一式给出算力估算，第二式给出注意力激活的显存估算——注意 $L^2$ 项，这是 DiT 把“不可预测的跳连求和”换成“可解析的平方项”的代价，也是它留给后续部署工作的主要负担。一个具体例子：当分辨率提高使 $L$ 翻倍时，算力约翻倍，但注意力激活显存约翻四倍；工程师可以在服务上线前就用这两个式子判断批大小上限，而不必先跑一遍生产流量。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-4\">四 · DiT 的替换：patchify、adaLN-Zero 与固定步数循环</h3>\n<p>论文的做法是把潜空间特征切成 token 序列，用标准 Transformer 块替换卷积主干。输入是 VAE 潜变量 $z_t$，经 patchify 线性投影成 token 序列，加位置编码后进入 $N$ 层 Transformer 块；每块含全局多头自注意力与前馈网络；时间步与类别条件经 adaLN-Zero 产生逐块的 scale/shift，注入每层归一化；输出经线性层与 unpatchify 还原为噪声预测：</p>\n<div class=\"formula\">$$\\hat{\\epsilon}=f_\\theta(\\mathrm{patchify}(z_t),t,c)$$</div>\n<p>三个设计选择对推理栈各有具体含义。patchify 决定序列长度：patch 越大，$L$ 越小，注意力平方项越小，但空间细节的重建能力下降；patch 越小，$L$ 越大，显存与带宽压力上升。这是推理容量规划里最直接的一个旋钮。adaLN-Zero 把条件注入做成逐块的缩放与偏移，不增加额外 token，因此有条件与无条件路径的推理图基本一致——对批调度而言，这意味着混合请求（部分带类别条件、部分不带）不需要两套图，连续批处理的实现复杂度下降。固定步数循环意味着每步重复 patchify、Transformer 前向与 unpatchify，步数增加时激活显存与带宽线性累积，这一点与 U-Net 相同，但累积的基数现在可以用 $L^2$ 显式估算。</p>\n<p>推理流程可以写成一段伪代码思路：请求到达后编码条件，进入去噪循环，每步 patchify 当前潜变量、跑 $N$ 层块、按采样器更新潜变量；循环结束后 unpatchify 并由 VAE 解码。代价集中在两处：每步的注意力矩阵（$L^2$ 规模）与 MLP 激活（$N\\cdot d\\cdot L$ 规模）；批处理摊薄权重读取，但注意力激活随批线性上升。一个具体例子：在单卡上把批从 4 提到 8，权重读取的摊薄收益在第二个批之后迅速递减，而注意力激活显存翻倍，折中点由 $M_{\\text{attn}}$ 的预算决定，而不是由权重容量决定。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-5\">五 · 缩放关系作为容量规划工具，以及它的边界</h3>\n<p>论文以 Gflops 为统一尺度，比较不同宽度、深度与 patch 配置，报告在相同或更低 Gflops 下 DiT 取得与 U-Net 相当或更好的生成质量，并给出质量随计算量提升的缩放趋势；具体 FID 数值与消融数值未在给定事实中给出。对推理工程而言，这个缩放关系的用途不是选模型，而是做容量规划：给定目标质量档位对应的 Gflops，可以直接反推 $N$、$d$、$L$ 的组合，再用上面的两式估算单步延迟与显存峰值，从而在服务上线前确定批大小与卡数。</p>\n<p>但这条缩放关系有明确边界，误用会直接导致线上事故。第一，Gflops 缩放结论是在图像分辨率下得到的，外推到长视频时 token 序列变长，注意力平方项使显存非线性上升，算力估算仍线性而显存估算已失效。第二，论文未涉及 NVFP4/FP8 量化、KV/激活缓存复用与分离式预填/解码，这些部署机制在 DiT 上的参数需要另行测量；在未验证数值稳定性的情况下对注意力激活做低精度量化，采样质量可能下降。第三，按图像分辨率设定的批大小不能直接搬到视频分块推理，分块与重叠策略会改变显存峰值。这三条边界共同指向一个判断：DiT 给出的是可分析的骨干形态，不是可直接套用的部署配方。</p>\n<table class=\"mini\"><thead><tr><th>维度</th><th>U-Net 主干</th><th>DiT 主干</th></tr></thead><tbody><tr><td>显存峰值来源</td><td>跳连激活求和，形状随层级漂移</td><td>注意力矩阵 $B\\cdot h\\cdot L^2$，可解析</td></tr><tr><td>算子序列</td><td>随分辨率变化，融合边界不规则</td><td>块内形状一致，融合与切分规则可复用</td></tr><tr><td>并行切分</td><td>跳连跨切分点，通信难对齐</td><td>按序列维或隐藏维切分，代价可估</td></tr><tr><td>条件注入</td><td>额外分支，推理图复杂</td><td>adaLN-Zero 逐块 scale/shift，图基本一致</td></tr><tr><td>容量规划</td><td>依赖实测扫参</td><td>由 $N,d,L$ 推算 Gflops 与激活</td></tr></tbody></table>\n<p>这张对照表的价值在于把“为什么非改不可”落到可操作的差异上：旧方案的每一行都要求工程师用生产流量换经验数据，新方案的每一行都允许在部署前用参数推算。代价是注意力平方项把显存压力从“多级求和”集中到“单一矩阵”，在长序列场景下这个集中点会成为新的瓶颈，需要分块与重叠策略来控制。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-6\">六 · 落在具体机制上：token 数是唯一需要盯住的量</h3>\n<p>把这一部分收束到一个工程判断上：在 DiT 推理栈里，token 数 $L$ 是唯一需要持续盯住的量。它由分辨率与 patch 尺寸决定，向上决定每步注意力矩阵的规模与激活显存，向下决定批大小的可行区间与吞吐上界。Blackwell 上的部署动作——NVFP4/FP8 量化点的选择、跨步激活缓存的复用粒度、按序列维的并行切分、连续批处理的批上限——全部以 $L$ 为自变量。当服务从 256×256 升到 512×512，或从图像扩到视频分块，第一件事不是调采样器，而是重算 $L$ 与 $L^2$ 项，再决定批大小与分块重叠；当 $L$ 大到注意力激活成为峰值，优先动作是调大 patch 尺寸或引入分块，而不是降精度赌数值稳定性。论文提供的不是一个部署配方，而是一个把扩散推理代价参数化的坐标系；在这个坐标系里，U-Net 时代靠实测扫参的容量规划，被替换成由 $N$、$d$、$L$ 三个数推出的估算，而估算的误差边界，正是后续量化、缓存与并行工作要逐项填上的空白。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-7\">七 · 从“一次前向”到“一条请求”：DiT 推理负载的四元组</h3>\n<p>在 DiT 的采样循环里，工程上真正需要被度量的负载不是单个去噪步，而是一条完整请求的四元组：<em>token 序列长度 S、采样步数 T、批大小 B、并发请求数 C</em>。S 由潜空间分辨率与 patch 尺寸决定，patchify 之后序列长度直接给出每步注意力矩阵的形状；T 由采样器与调度决定，是固定循环次数；B 与 C 则把单步代价放大成系统代价。四者不是独立的：给定单卡显存上限，S 越大，允许的 B 越小；B 越小，权重读取摊薄越差，单 token 的有效带宽成本越高。这条约束链就是负载塑造方案的起点。</p>\n<p>可核查的测量口径必须落到“每步”粒度。对一条请求，记录每步的 <code>S</code>、注意力矩阵元素数 <code>S²</code>、MLP 激活元素数 <code>S·d</code>（d 为隐藏维），以及该步的墙钟时间。系统级则记录请求到达率 λ、平均排队时延、端到端时延 P99、以及每步激活显存峰值。没有这五个量，任何“吞吐提升”的说法都无法复核。DiT 的推理图在条件注入上很干净——adaLN-Zero 只产生逐块 scale/shift，不额外增加 token，因此 S 在整个采样循环中恒定，这让负载形态比自回归解码更规整，也让测量口径可以简化为“单步代价 × T × 并发”。</p>\n<div class=\"formula\">$$M_{\\text{act}}(B,S) \\approx B\\cdot\\big(\\alpha S^2 + \\beta S d\\big),\\qquad \\text{throughput}\\approx \\frac{B\\cdot C\\cdot T_{\\text{req}}}{t_{\\text{step}}(B,S)}$$</div>\n<p>式中 α、β 是与层数、头数、是否重计算相关的系数，需在目标卡上实测标定，不能从论文的 Gflops 缩放趋势直接外推。举例：同一 DiT 配置下把潜分辨率提高一档，S 翻倍，注意力项 <code>S²</code> 变为四倍，而 MLP 项只翻倍；此时若维持原批大小，显存峰值由注意力主导而超标，工程上要么减小 B，要么对注意力做分块计算，代价是每步多一次 kernel 启动与部分重读。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-8\">八 · 输入长度分布：patch 尺寸是隐式的负载旋钮</h3>\n<p>DiT 没有“用户输入长度”这一说，但存在等价物：潜特征被 patchify 切成的 token 数。分辨率固定时，patch 尺寸 p 决定 <code>S=(H/p)·(W/p)</code>；p 减半，S 变四倍，Gflops 与注意力激活同步抬升。论文的消融显示 patch 大小与宽度对 Gflops—质量关系影响显著，这意味着部署侧存在一个明确的权衡：选大 patch 换取更短序列与更低显存，选小 patch 换取质量但把负载推向注意力瓶颈。负载分布因此不是自然给定的，而是被模型配置反向塑造的。</p>\n<p>对服务方而言，真实负载分布是“多档 S 混合到达”。若所有请求共用同一模型实例，调度器必须按 S 分桶，否则一个高分辨率请求会把整批的显存峰值拉高，迫使同批低分辨率请求一起降速。可核查口径：按 S 分桶统计到达比例、每桶的平均 B 与 P99 时延、以及桶间切换导致的权重重载次数。分桶过细会增加实例数与权重驻留压力，分桶过粗则长尾请求拖累整体。一个具体做法是把 S 划分为若干离散档位，每档绑定固定的最大批大小，档内做连续批处理，档间通过请求队列隔离。</p>\n<ul>\n<li>机制：patch 尺寸与分辨率共同决定 S，S 决定每步注意力规模；条件注入不改变 S，故同一请求内负载恒定。</li>\n<li>代价：S 翻倍时注意力激活约四倍、MLP 激活约两倍，显存峰值由前者主导；带宽侧每步需重读权重，B 越小摊薄越差。</li>\n<li>口径：按 S 分桶统计到达率与 P99，记录桶内平均批大小与每步激活峰值，避免用全局均值掩盖长尾。</li>\n</ul>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-9\">九 · 并发与批大小：摊薄权重读取与激活线性上升的对冲</h3>\n<p>扩散采样是固定 T 步的循环，每步都要完整读一遍 N 层 Transformer 的权重。单请求时权重读取是纯开销；把 B 条请求拼成一批，同一份权重服务 B 次前向，权重带宽成本被摊薄。但注意力激活随 B 线性上升，MLP 激活同样线性上升，显存峰值随之抬升。这就是 DiT 推理最核心的对冲：吞吐随 B 上升而显存随 B 上升，二者在显存上限处相交，交点即最优批大小。</p>\n<p>可核查的测量方法是固定 S 与 T，扫 B 从 1 到显存上限，记录每步时间 <code>t_step(B)</code>、每秒 token 数、以及激活峰值。若 <code>t_step</code> 在某个 B 之后不再下降（权重读取已不再是瓶颈，算力或带宽饱和），则该点之后增大 B 只增加显存不增加吞吐。并发 C 与批大小 B 不是一回事：C 是排队中的请求数，B 是同时进入一次前向的请求数。C 大于 B 时，多余请求在队列中等待，端到端时延被拉长；C 小于 B 时，批内空位浪费权重摊薄机会。工程判断是让 B 贴近显存与算力共同决定的最优点，让 C 略高于 B 以吸收到达抖动，同时用连续批处理在请求完成与到达之间重填批内空位。</p>\n<div class=\"formula\">$$\\text{cost per request} = \\frac{t_{\\text{step}}(B,S)\\cdot T}{B} + \\frac{\\text{queue wait}}{1}$$</div>\n<p>举例：某 DiT 实例在 S 固定时，B 从 1 增至某值前每步时间基本不变（权重读取主导），超过该值后每步时间随 B 上升，说明算力饱和；此时继续增大 B 会让单请求时延变差而吞吐不再提升。这个拐点必须在目标硬件上用上述扫描实测，不能由论文的 Gflops 数字推算。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-10\">十 · SLO 与长尾：固定步数循环下的时延构成</h3>\n<p>DiT 请求的端到端时延可拆为：排队等待、T 步去噪、以及 unpatchify 与 VAE 解码。去噪部分是 <code>T·t_step</code>，其中 T 由采样配置决定，是时延的硬下限；解码阶段显存峰值与分块策略相关，往往是长尾的来源——解码的分块数随分辨率上升，块间串行导致尾延迟拉长。SLO 通常按 P99 而非均值定义，因此长尾请求（高 S、大 T、解码分块多）决定容量。</p>\n<p>可核查口径：分别记录排队时延、去噪时延、解码时延的 P50/P99，并记录每类请求的 S 与 T。若 P99 主要由排队贡献，说明 C 相对 B 过高或批调度不够连续；若由解码贡献，说明需要按分辨率做解码分块并行或把解码移出主实例。论文未给出批调度与 SLO 吞吐数据，因此这些量只能实测。一个具体判断：当 T 较大时，去噪时延的方差很小（每步结构相同），P99 与 P50 的差距主要来自排队与解码，调度优化的收益集中在后者。</p>\n<table class=\"mini\"><thead><tr><th>时延分量</th><th>决定因素</th><th>长尾来源</th><th>可核查口径</th></tr></thead><tbody><tr><td>排队</td><td>C 与 B 的关系、到达抖动</td><td>突发到达、批内空位</td><td>排队时延 P99、队列深度时间序列</td></tr><tr><td>去噪</td><td>T、t_step(B,S)</td><td>高 S 请求、批内最慢者</td><td>每步时间分布、按 S 分桶的 T·t_step</td></tr><tr><td>解码</td><td>分辨率、分块策略</td><td>高分块串行、显存峰值</td><td>解码时延 P99、解码显存峰值</td></tr></tbody></table>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-11\">十一 · 方案反过来限制负载：容量规划中的闭环</h3>\n<p>负载塑造方案，方案也塑造负载。一旦服务方按 S 分桶并绑定最大批大小，可接受的分辨率档位就被固定；一旦显存上限决定 B，单实例能承载的并发 C 就被固定；一旦 T 被采样配置锁定，单请求最短时延就被锁定。容量规划因此是一个闭环：给定 SLO（P99 时延上限）与硬件显存，反解出允许的 (B, C, S 档位, T) 组合，再据此设定准入控制——超出档位的请求要么排队、要么降级到更大 patch 的快速路径、要么拒绝。</p>\n<p>可核查的规划口径是“每实例每秒完成的请求数”与“每请求的显存占用”两个量，二者相乘不得超过显存与带宽预算。具体机制：以 <code>B·(αS²+βSd)</code> 估算激活峰值，加上权重常驻与解码缓冲，得到单实例显存占用；以 <code>B/T·t_step</code> 的倒数估算吞吐上限；两者取小作为准入阈值。举例：若某档 S 下激活峰值已接近显存上限，则 B 只能取小值，吞吐受限于权重读取而非算力，此时提高吞吐的正确方向是增大 patch（降 S）而不是加卡——加卡只增加权重副本，不改变单请求的注意力激活。这正是 DiT 负载形态对方案的反向约束：注意力平方项使得“堆硬件”在长序列档位上收益递减。</p>\n<ul>\n<li>机制：准入控制按 (S 档位, B, C, T) 四元组设定阈值，超限请求降级或排队。</li>\n<li>公式：单实例显存 ≈ 权重 + <code>B·(αS²+βSd)</code> + 解码缓冲；吞吐上限 ≈ <code>B/(T·t_step)</code>。</li>\n<li>代价：长序列档位上注意力激活主导显存，增加实例数只复制权重、不降低单请求激活，吞吐提升有限。</li>\n</ul>\n<p>落到工程判断上：DiT 推理的容量规划不应以 Gflops 为唯一尺度，而应以“每档 S 下的激活峰值与每步时间”为基本测量单元，把批大小、并发与 SLO 三者绑定成一张可复核的表；任何偏离该表的配置变更，都必须重新实测 <code>t_step(B,S)</code> 与激活峰值，而不是从论文的缩放趋势外推。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-12\">十二 · 负载画像：token 序列长度如何反过来定义 DiT 推理方案的可行域</h3>\n\n<p>DiT 的请求形态与自回归 LLM 有本质差异：一次采样请求不是「一个 prompt 进、一串 token 出」，而是固定步数循环里反复对同一 token 序列做前向。因此负载的第一维不是输入长度分布，而是<strong>单请求 token 序列长度</strong> L = (H/p)·(W/p)（图像）或再乘帧数与时间 patch（视频），由分辨率与 patch 尺寸共同决定。第二个维度是采样步数 T，第三个才是并发批大小 B。三者共同决定每步激活显存峰值，而非权重显存：全局注意力矩阵规模为 B·heads·L²，随 L 平方增长、随 B 线性增长。这意味着容量规划不能按「显存减去权重再除以单请求占用」的线性外推做，L 翻倍时单请求激活涨四倍，批大小必须同步下调。可核查口径是：固定分辨率与 patch 配置，逐档扫描 B，记录每步注意力激活峰值与端到端吞吐（样本/秒），画出吞吐饱和点——饱和点之前摊薄权重读取有效，之后纯属显存换吞吐的亏损区。</p>\n\n<p>步数 T 是长尾的来源。扩散采样无自回归 KV，跨步缓存只能针对条件嵌入与部分中间激活，复用收益有限，故单请求延迟近似正比于 T·(注意力 + MLP) 的单步代价。若服务端按平均步数做 SLO 承诺，尾部长步数请求（高分辨率、多步采样器）会把 P99 拉穿。工程上应把 T 与 L 一起作为路由键：短序列高步数与长序列低步数分池调度，避免同一 batch 内混入不同 T 造成同步空转——固定步数循环的批处理只在步数对齐时才摊薄权重读取，步数不齐的请求混批会让短请求等待长请求的剩余步，等效吞吐塌陷。公式上，批内有效利用率可写成</p>\n\n<div class=\"formula\">$$\\eta=\\frac{\\sum_i T_i}{T_{\\max}\\cdot B},\\quad T_{\\max}=\\max_i T_i$$</div>\n\n<p>η 低于某阈值即应拆批，这是调度器必须显式测量的量，而非凭经验设 batch size 上限。</p>\n\n<p>方案反过来限制负载，体现在三个硬边界。其一，patch 尺寸是方案侧旋钮却决定负载侧 L：调大 patch 降 L 与 Gflops，但空间细节被压掉，质量回退，等价于用质量换显存，不能当作免费扩容手段。其二，全局注意力使长视频必须分块加重叠，重叠区带来重复计算，实际 token 吞吐低于名义值，容量规划须按「有效 token 数 × (1+重叠率)」计费。其三，量化边界：NVFP4/FP8 可用于权重与 MLP 激活以压带宽，但注意力 softmax 前后的激活对数值稳定性敏感，论文未给量化实验，部署前必须逐层做质量回归，不能把 Gflops 缩放结论直接外推到低精度路径。失效条件很明确：按图像分辨率标定的批大小直接搬到视频分块推理，L 骤增使 B·L² 越过显存上限，出现 OOM 而非优雅降级；此时唯一可核查的兜底是分块粒度与批大小的联合扫描表。</p>\n\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>测量口径</th><th>方案侧约束</th></tr></thead><tbody><tr><td>序列长度 L</td><td>分辨率/patch 推导，逐档记录注意力激活峰值</td><td>patch 尺寸、分块重叠率</td></tr><tr><td>步数 T</td><td>P50/P99 步数分布，批内 η</td><td>步数对齐分池，拆批阈值</td></tr><tr><td>批大小 B</td><td>吞吐饱和点扫描</td><td>激活显存上限，非权重上限</td></tr></tbody></table>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-13\">十三 · 从 Gflops 到 kernel：DiT 前向的算子序列与精度落点</h3>\n<p>DiT 的一次去噪步在算子层面是一条固定序列：patchify 线性投影 → 位置编码加性融合 → N 层（LayerNorm → 全局多头自注意力 → 残差 → LayerNorm → MLP → 残差，每层归一化的 scale/shift 来自 adaLN-Zero）→ 最终 LayerNorm → 线性层 → unpatchify。这条序列对 Blackwell 的意义在于：它没有 U-Net 的下采样堆叠与跳连，算子边界干净，融合规则可按 Transformer 统一规划。真正决定精度落点的是三类算子——GEMM（patchify 投影、QKV 投影、注意力输出投影、MLP 的两级投影）、注意力内部的 QK^T 与 softmax·V、以及逐元素的归一化与 adaLN 调制。</p>\n<p>论文给出的规模关系是</p>\n<div class=\"formula\">$$\\mathrm{Gflops}\\approx k\\cdot N\\cdot d^2\\cdot L$$</div>\n<p>逐项解释：$N$ 为 Transformer 块数（深度），$d$ 为隐藏维（宽度），$L$ 为 token 序列长度（由潜空间分辨率与 patch 尺寸决定），$k$ 为把每块前向的 GEMM 与注意力项折算成常数因子的系数。注意该式把注意力项并入 $k$ 的近似——严格地说注意力贡献正比于 $L^2 d$，在 $L$ 较大时这一项会脱离线性估计，这正是后文显存非线性上升的根源。工程上应把该式拆成两部分使用：权重侧 GEMM 量 $\\propto N d^2 L$，注意力侧 $\\propto N L^2 d$，前者决定权重带宽与 Tensor Core 占用，后者决定激活显存与 softmax 开销。</p>\n<p>精度落点的具体判断：patchify 与 QKV 投影是权重主导的 GEMM，适合 FP8 甚至 NVFP4 权重配高精度累加；注意力内部的 QK^T 对数值范围敏感，softmax 前的 logits 若量化过粗会改变注意力分布，进而改变采样轨迹；adaLN-Zero 产生的 scale/shift 是逐通道小向量，量化误差会被逐层放大，宜保留 BF16。代价层面：把 QKV 投影从 BF16 降到 FP8，权重读取字节数减半，在权重带宽受限的小批解码式采样中直接改善每步延迟；但若把 softmax 前的 QK^T 也压到 FP8，需要额外的行最大值缩放与误差补偿，否则采样质量下降。以一个 $L=4096$、$d=1152$、$N=28$ 的配置为例，注意力矩阵单头规模为 $4096^2$，即使只算一次也要占用可观的片上与片外带宽，任何在该矩阵上的低精度尝试都必须先做数值验证。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-14\">十四 · 数据类型分层：FP16/BF16、FP8、NVFP4 在扩散采样中的分工</h3>\n<p>扩散采样与自回归解码的数值需求不同：后者有 KV cache 的长程累积误差，前者是固定步数循环、每步重新计算全序列，误差不跨步累积但会在步间通过潜变量更新传播。这决定了精度分层策略：权重可以激进，激活需保守，累加必须高精度。</p>\n<ul>\n<li>BF16 作为基准精度：动态范围与 FP32 同阶，适合 adaLN 调制、LayerNorm、残差累加与最终输出投影。这些逐元素或归约算子对 Tensor Core 吞吐不敏感，但对数值范围敏感，降精度收益小而风险大。</li>\n<li>FP8（E4M3 为主）用于权重与主要 GEMM 的激活输入：QKV 投影、注意力输出投影、MLP 两级投影。E4M3 的尾数位足以表达扩散激活的分布，配合 per-tensor 或 per-channel 缩放因子即可。E5M2 动态范围更大但尾数更少，仅在激活存在极端离群值时作为备选。</li>\n<li>NVFP4 用于权重侧：块级缩放（微块共享指数）使 4 位权重在 Blackwell 第五代 Tensor Core 上可直接参与 MMA，权重带宽压到 BF16 的四分之一。扩散模型的权重在采样期间不变，量化误差可离线校准，是 NVFP4 最合适的落点；激活侧用 NVFP4 则需逐 token 动态缩放，风险显著更高。</li>\n</ul>\n<p>代价对比可以用一个简单的带宽账说明：设某层权重为 $W$ 字节，批大小为 $B$，则权重读取摊薄后每请求的字节数为 $W/B$。当 $B$ 小（高分辨率、长序列场景被迫小批）时，权重带宽主导每步延迟，NVFP4 的收益最直接；当 $B$ 大时，激活带宽与注意力开销主导，权重精度下降的收益被稀释。因此精度方案必须与批调度联合决策，而不是全局一刀切。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-15\">十五 · 累加精度与误差传播：为什么 MMA 的累加器不能跟着降</h3>\n<p>Tensor Core 的低精度输入配高精度累加是这套精度分层的前提。以 FP8 GEMM 为例，输入为 E4M3，累加在 FP32 中进行，输出再量化回 BF16 或 FP8 供下一层使用。误差来源有三：输入量化的舍入误差、累加过程中的舍入（若累加器位宽不足）、以及输出再量化。扩散采样对这些误差的容忍度取决于误差是否在步间被放大。</p>\n<div class=\"formula\">$$\\hat{z}_{t-1}=\\mathrm{step}\\big(\\hat{\\epsilon}_\\theta(z_t,t,c),\\,z_t\\big),\\qquad \\|\\hat{\\epsilon}_\\theta-\\epsilon_\\theta\\|_2\\le \\sum_{l=1}^{N}\\|\\Delta_l\\|_2$$</div>\n<p>逐项解释：$\\hat{\\epsilon}_\\theta$ 为量化后网络输出的噪声预测，$\\epsilon_\\theta$ 为高精度参考；$\\Delta_l$ 为第 $l$ 层的输出偏差，包含输入量化、累加与再量化三部分。该不等式说明逐层偏差在深度方向上是可加的——深度 $N$ 越大，末端偏差上界越松。扩散采样器每步用 $\\hat{\\epsilon}_\\theta$ 更新潜变量，偏差通过采样器系数映射到 $z_{t-1}$，再进入下一步的前向。由于每步都重新计算，误差不会被无限累积，但会在步间形成有偏的轨迹漂移，表现为细节退化或条件遵循减弱。</p>\n<p>工程含义：累加器必须保持 FP32，尤其在 MLP 的两级投影与注意力的 $QK^T$ 上；输出再量化的粒度应按通道而非按张量，以减少逐层偏差的叠加。对 adaLN-Zero 的 scale/shift 路径，累加与调制都应留在 BF16/FP32，因为该路径的输出直接乘在归一化激活上，误差会等比放大到整层。代价上，FP32 累加不改变 Tensor Core 的输入带宽，只影响寄存器与流水占用；在 tcgen05 的 MMA 流水里，累加器驻留在 TMEM 中，位宽增加会占用更多 TMEM 容量，进而限制可并发的 MMA 数量与 tile 尺寸——这是精度选择与吞吐之间的真实耦合点。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-16\">十六 · Blackwell 特性映射：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core</h3>\n<p>把上述精度分层落到 SM100/SM103 上，需要理解四个机制的配合方式。tcgen05 是这一代的张量核心指令族，MMA 由单个 warp 发起、异步执行，结果写入 TMEM 而非寄存器堆；TMEM 是每 SM 专用的片上暂存，承载累加器与操作数分块，其容量直接约束 tile 形状与在飞 MMA 数量；2-SM MMA 让一对 SM 协同完成一次更大的 MMA，把两个 SM 的 TMEM 与算力拼成一个逻辑单元，适合 $d$ 较大的投影层；第五代 Tensor Core 在硬件上支持 FP4/FP8 输入配高精度累加，使 NVFP4 权重路径无需软件反量化即可进入 MMA。</p>\n<p>对 DiT 的映射判断：QKV 投影与 MLP 的第一级投影是 $d\\times d$ 量级的 GEMM，宽度 $d$ 较大时用 2-SM MMA 可减少分块边界与跨 SM 的数据搬运，提升 Tensor Core 占用率；注意力内部的 $QK^T$ 形状为 $L\\times L$，当 $L$ 很大而头维较小时，2-SM 拼接的收益取决于 tile 是否能对齐，否则协同开销会吃掉收益。TMEM 的容量约束在注意力路径上更明显：softmax 需要把 logits 从 TMEM 搬到寄存器或共享内存做归约，再写回参与 $PV$ 乘法，这一搬移是注意力 kernel 的主要非 GEMM 开销。</p>\n<p>代价的具体形态：TMEM 容量固定，若累加器用 FP32 且 tile 取得大，则在飞 MMA 数减少，流水出现气泡；若为容纳更多在飞 MMA 而缩小 tile，则 2-SM 协同的分块边界增多，跨 SM 通信上升。这是一个容量—并行度—通信的三方权衡，需按 $d$ 与 $L$ 的实际形状调参，而不是套用固定 tile。功耗侧，FP4 路径在相同 Gflops 下 Tensor Core 活动时间缩短，但权重解压与缩放因子应用的逐元素开销转移到 CUDA core，需在 kernel 融合时一并考虑。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-17\">十七 · kernel 融合与数值稳定性的交界：adaLN、softmax 与残差</h3>\n<p>DiT 的推理图里有两处融合必须与精度决策一起做。第一处是 LayerNorm 与 adaLN-Zero 调制：归一化后立即乘以逐通道 scale 再加 shift，若把这三步拆成独立 kernel，激活要往返显存三次；融合成单趟 kernel 可把中间激活留在寄存器，代价是 scale/shift 必须以 BF16 精度参与，不能为了省带宽压到 FP8。第二处是残差加法与下一次归一化的衔接：残差累加应在 FP32 或 BF16 中完成，再进入归一化，若在 FP8 域累加，多层残差的动态范围会被截断。</p>\n<p>softmax 是数值稳定性最脆弱的位置。全局注意力的 logits 矩阵规模为 $B\\times H\\times L\\times L$，行最大值归约需要跨 tile 通信；若 logits 以 FP8 存储，行最大值与指数运算的输入范围受限，需要在线缩放（running max）配合。一个可操作的伪代码思路是：分块计算 $QK^T$ 得到 FP32 累加的 logits tile，就地做行最大值与指数归约，得到未归一化的注意力权重并以 BF16 暂存，最后与 $V$ 做第二次 GEMM 并在 FP32 中累加。这样 softmax 的输入始终是高精度累加结果，只有权重存储被降到 BF16，误差可控。</p>\n<p>系统代价：融合减少显存往返，直接降低每步的激活带宽；但融合 kernel 的寄存器压力上升，占用率下降，在长序列小批场景下可能反而拉长每步延迟。以 $L=4096$、批大小为 1 的高分辨率采样为例，注意力激活是显存峰值的主要构成，融合 softmax 与残差可以把峰值压到可容纳单卡的程度，代价是 kernel 内部的同步点增多，Tensor Core 与 CUDA core 的重叠窗口变窄。工程判断是：先按显存峰值确定是否必须融合，再按每步延迟决定融合的粒度。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-18\">十八 · 精度方案与容量规划的耦合：从 token 数反推可行配置</h3>\n<p>精度不是孤立选择，它改变的是每步的显存峰值与带宽需求，进而改变可行的批大小与序列长度。注意力激活随 $B\\cdot H\\cdot L^2$ 增长，权重占用随 $N\\cdot d^2$ 与精度字节数缩放。给定单卡显存上限，可行配置满足</p>\n<div class=\"formula\">$$B\\cdot H\\cdot L^2\\cdot b_{\\mathrm{act}}+N\\cdot d^2\\cdot b_{w}\\le M_{\\mathrm{avail}}$$</div>\n<p>逐项解释：$b_{\\mathrm{act}}$ 为注意力激活每元素的字节数（BF16 为 2，FP8 为 1），$b_w$ 为权重每参数字节数（NVFP4 为 0.5 加缩放开销），$M_{\\mathrm{avail}}$ 为扣除框架与解码阶段峰值后的可用显存。该式说明：权重精度下降释放的是第二项，对长序列场景的帮助有限；激活精度下降释放的是第一项，但直接触及 softmax 稳定性。因此高分辨率、长 token 序列的 DiT 推理，优先在权重侧用 NVFP4、在激活侧保持 BF16 的注意力权重，而不是全面低精度。</p>\n<p>具体例子：一个 $L=8192$ 的视频分块采样请求，若注意力权重用 BF16，第一项随 $L^2$ 迅速吃掉显存，批大小被迫降到 1；若把注意力权重降到 FP8 并把 softmax 归约留在 FP32，第一项减半，可容纳的批大小翻倍，吞吐改善但需验证采样质量。反过来，若权重已用 NVFP4 而激活仍是 BF16，则权重项不再是瓶颈，进一步压权重精度没有收益，应把工程投入转向注意力 kernel 的分块与融合。容量规划的顺序应是：先由 $L$ 与 $B$ 定激活峰值，再由剩余显存定权重精度档位，最后用实测的每步延迟校验 Tensor Core 占用是否被 TMEM 容量限制。这条顺序把精度选择从“全局开关”变成“按瓶颈分配的预算”，也是 DiT 这类固定步数循环骨干在 Blackwell 上做部署参数化的基本方法。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-19\">十九 · 精度下探的边界：DiT 在 Blackwell 上量化到哪一步会失效</h3>\n<p>DiT 的推理图对量化相对友好，因为它没有 U-Net 那种跨层跳连带来的多尺度激活拼接，算子序列是规整的“归一化→全局注意力→MLP”重复，权重与激活的分布可按层统计。但友好不等于无条件：全局注意力矩阵随 token 数平方增长，softmax 前的 logits 动态范围随序列长度与批大小漂移，这是 FP8 乃至 NVFP4 最先失效的位置。工程上可把每步代价写成 <span class=\"formula\">$$A_{\\text{attn}}=B\\cdot H\\cdot S^2\\cdot b_{\\text{acc}},\\quad A_{\\text{mlp}}=B\\cdot S\\cdot d\\cdot b_{w}$$</span> 其中 $B$ 为批、$H$ 为头数、$S$ 为 token 数、$d$ 为宽度、$b$ 为字节数；$S^2$ 项决定注意力激活显存，$S\\cdot d$ 项决定 MLP 带宽。把 $b_{\\text{acc}}$ 从 FP16 压到 FP8，注意力激活显存减半、带宽减半，但 logits 的量化误差会经 softmax 放大——这是 DiT 量化最典型的失效条件：序列越长、条件 scale/shift 越极端，softmax 饱和越明显，低精度 logits 直接改变注意力权重分布，采样质量下降而不报错。</p>\n<p>Blackwell 的 tcgen05 与 TMEM 改变了这个权衡的形状。第五代 Tensor Core 的 2-SM MMA 让两个 SM 协作完成一次大 MMA，累加器驻留 TMEM 而非寄存器堆，FP8 输入的累加仍在 FP32 通路完成，因此“输入低精度、累加高精度”成为默认配置，而非需要手工拼装的技巧。对 DiT 而言，这意味着注意力 QK^T 与 PV 可用 FP8 输入配 FP32 累加，把 $b_{\\text{acc}}$ 的显存压力从累加器转移到输入侧；代价是 TMEM 容量有限，2-SM MMA 要求 tile 形状与 SM 配对匹配，patch 尺寸与头维度不能任意切，否则 tile 被迫缩小、Tensor Core 利用率下降。工程判断是：先按 $S$ 与头维度选定 MMA tile，再决定 FP8 还是 NVFP4，而不是反过来。</p>\n<p>NVFP4 的边界更窄。它把权重与激活压到 4 位并配块级缩放，权重侧通常可承受，激活侧在 MLP 上尚可，但注意力 logits 与 softmax 输出对 4 位块缩放极敏感；adaLN-Zero 产生的逐块 scale/shift 若也被量化，条件注入的细微调制会被抹平，表现为类别条件生成时多样性塌缩。可行的折中是混合精度：MLP 与线性投影走 NVFP4，注意力 QK^T 保 FP8、PV 保 FP8 配 FP32 累加，归一化与 softmax 保 BF16。系统代价要按最慢一环算：只要有一层保 BF16，该层的带宽与 Tensor Core 吞吐就按 BF16 计，端到端加速比被这一层封顶。下表给出各精度档在 DiT 推理中的适用位置与主要代价。</p>\n<table class=\"mini\"><thead><tr><th>精度档</th><th>适用位置</th><th>主要代价</th></tr></thead><tbody><tr><td>BF16</td><td>归一化、softmax、条件注入</td><td>带宽与吞吐按 BF16 封顶</td></tr><tr><td>FP8</td><td>QK^T、PV、线性投影</td><td>logits 量化误差经 softmax 放大</td></tr><tr><td>NVFP4</td><td>MLP、权重</td><td>块缩放抹平条件调制，需混合精度</td></tr></tbody></table>\n<p>具体例子：固定 $d$ 与 $N$、把 patch 尺寸减半使 $S$ 翻倍，注意力激活按 $S^2$ 变为四倍，此时若把注意力输入从 BF16 降到 FP8，激活减半只能抵消一部分增量，显存峰值仍上升；若进一步降到 NVFP4，softmax 饱和导致的采样偏差在长序列上累积到不可忽略。结论落在机制上：DiT 的量化上限由注意力 logits 的数值稳定性决定，而非权重侧；Blackwell 的 FP32 累加与 TMEM 把这条上限抬高了一档，但抬高的幅度取决于 tile 形状能否与 2-SM MMA 对齐，对齐失败时低精度带来的吞吐收益会被 tile 缩小的损失吃掉。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-20\">二十 · 显存账本的三条主线：权重、激活、跨步缓存</h3>\n<p>DiT 的推理显存在 Blackwell 上要拆成三本独立的账：权重账、激活账、跨步缓存账。权重账最稳定，参数量由宽度 <em>d</em>、深度 <em>N</em> 与 MLP 扩张比决定，每层约含 4<em>d</em>²（注意力投影）加 8<em>d</em>²（MLP 两矩阵，扩张比 4）量级的参数，再叠加 adaLN-Zero 的逐块调制分支。激活账是真正吃显存的部分：每步 patchify 后的 token 序列长度为 <em>S</em>，全局注意力要物化 <em>S</em>×<em>S</em> 的分数矩阵（多头按头数分摊但总量不变），加上 MLP 中间激活 4<em>d</em>·<em>S</em>。跨步缓存账是扩散特有的：采样是固定步数循环，条件嵌入（时间步、类别经 adaLN-Zero 生成的 scale/shift）在整个循环里不变，属于可复用项；而每步的潜变量与注意力中间结果默认丢弃，若要做跨步复用（缓存相邻步的注意力或 MLP 激活），就要额外占显存。</p>\n<p>三本账的量级差异决定了优化顺序。以图像 DiT 为例，权重在 FP16 下按参数量线性折算；激活在 <em>S</em> 较大时按 <em>S</em>² 主导；跨步缓存则随复用深度线性增长。工程判断是：先确认注意力激活是否已成为峰值，再决定是否值得为跨步复用付出显存。若 <em>S</em> 小（大 patch、低分辨率），权重账占比上升，量化权重收益更直接；若 <em>S</em> 大（小 patch、高分辨率、视频多帧），激活账压倒一切，此时压缩 KV/激活比压缩权重更有效。</p>\n<div class=\"formula\">$$M_{\\text{peak}} \\approx \\underbrace{P\\cdot b_w}_{\\text{权重}} + \\underbrace{B\\cdot S\\cdot d\\cdot b_a\\cdot c_{\\text{mlp}} + B\\cdot h\\cdot S^2\\cdot b_a}_{\\text{激活}} + \\underbrace{M_{\\text{cache}}(B,S,N_{\\text{reuse}})}_{\\text{跨步缓存}}$$</div>\n<p>其中 <em>B</em> 为批大小，<em>b<sub>w</sub></em>、<em>b<sub>a</sub></em> 为权重与激活的每元素字节数，<em>c<sub>mlp</sub></em> 为 MLP 中间激活的倍数，<em>h</em> 为头数（分数矩阵按头分摊但总量与 <em>h</em> 无关，此处写法强调按头切分后的单头视图）。这个式子可直接复算：给定 <em>d</em>、<em>N</em>、<em>S</em>、<em>B</em> 与精度，逐项相加即得单卡峰值下限，再乘上框架的临时缓冲系数（通常 1.1–1.3）得到规划值。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-21\">二十一 · 分页与分块：把 S² 注意力拆成可管理的块</h3>\n<p>DiT 没有自回归解码的 KV cache，但有等价物：每步的注意力分数矩阵与值矩阵。全局注意力一次性物化 <em>S</em>×<em>S</em> 在长序列下不可行，工程上必须做分块（tiling）。FlashAttention 式的在线 softmax 把分数矩阵切成 <em>B<sub>q</sub></em>×<em>B<sub>k</sub></em> 的块，逐块累加分子与分母，显存从 <em>O</em>(<em>S</em>²) 降到 <em>O</em>(<em>S</em>·<em>B<sub>k</sub></em>)，代价是值矩阵需要被多次读取，HBM 带宽成为新瓶颈。分页（paging）在这里的含义不是操作系统式的页表，而是把 token 序列按固定块大小组织成可寻址的块表，使不同请求、不同分辨率、不同帧数的序列能共享同一块池，避免为每个请求预分配最大长度。</p>\n<p>对视频扩散，分页尤其关键：帧数可变导致 <em>S</em> 在请求间差异极大，按最大 <em>S</em> 预分配会让短请求浪费大量显存。块表按实际 <em>S</em> 分配，配合分块注意力，使显存占用与真实序列长度成正比而非与上限成正比。代价是块表的间接寻址增加了一次索引读取，在带宽敏感的场景下需要把块表常驻片上或 L2。伪代码思路：</p>\n<ul>\n<li>按 <em>B<sub>k</sub></em> 切分 key/value 序列，为每块分配物理块号，写入块表；</li>\n<li>查询块按 <em>B<sub>q</sub></em> 切分，对每个查询块遍历块表，做块内 QK<sup>T</sup>、在线更新 softmax 统计量、累加输出；</li>\n<li>块表在请求结束时归还块池，供后续请求复用。</li>\n</ul>\n<p>系统代价体现在两处：一是分块后值矩阵被重复读取，HBM 带宽消耗上升，<em>B<sub>k</sub></em> 越小重复越多；二是块表寻址带来的额外延迟，在高并发下与调度器交互频繁。工程上 <em>B<sub>k</sub></em> 的选择要在带宽与片上容量间折中，通常取使单块能驻留 SMEM 或 TMEM 的尺寸。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-22\">二十二 · 压缩与复用：精度、跨步、条件三条路径</h3>\n<p>压缩的第一条路径是精度。Blackwell 的 NVFP4/FP8 可用于权重与激活，但 DiT 的注意力分数矩阵对数值稳定性敏感：softmax 前的分数动态范围大，FP8 直接量化可能改变注意力分布，进而影响采样质量。稳妥做法是权重走 FP8/FP4、激活的 MLP 部分走 FP8，而注意力分数矩阵保持较高精度或采用分块缩放（per-block scaling）的 FP8。代价是混合精度带来额外的缩放因子存储与转换开销，收益是权重带宽与 MLP 激活带宽成倍下降。</p>\n<p>第二条路径是跨步复用。扩散采样相邻步的潜变量高度相关，注意力图与 MLP 激活在相邻步间变化有限，因此可以缓存上一步的部分中间结果供下一步近似复用，减少重复计算与重复读取。这与自回归的 KV cache 不同：没有增长的序列维，缓存的是固定形状的中间张量，复用深度 <em>N<sub>reuse</sub></em> 决定额外显存 <em>M<sub>cache</sub></em> 与节省的带宽。复用比例越高，显存账越重，且近似误差会累积到采样轨迹上，需要在质量与显存间定阈值。</p>\n<p>第三条路径是条件复用。adaLN-Zero 产生的逐块 scale/shift 只依赖时间步与类别，与 token 内容无关，在整个采样循环中可预先算好并常驻显存，避免每步重复计算条件分支。这部分显存很小（<em>N</em> 层 × 2<em>d</em> 个系数），但省下的是每步的调制计算与条件编码读取，属于低成本高确定性的优化。三条路径的优先级判断：条件复用无条件做；精度压缩看数值验证结果；跨步复用只在激活账已成峰值且质量余量足够时启用。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-23\">二十三 · 卸载：把哪本账挪出 HBM</h3>\n<p>卸载（offload）在 DiT 推理里的对象是权重与跨步缓存，而不是激活。激活是每步现算现用的，卸载到 host 再取回会引入 PCIe 往返，延迟不可接受。权重则不同：若批大小很小、权重账占比高，可以把部分层的权重放在 host 内存，按层流水取回，用计算掩盖传输。跨步缓存若复用深度大，也可放在 host 侧，按需换入。代价是 PCIe 带宽成为新的瓶颈，且流水深度需要与层计算时间匹配，否则出现气泡。</p>\n<p>卸载的工程判断依据是带宽比：若单层计算时间大于该层权重的传输时间，卸载可行；否则卸载只会拉长每步延迟。在 GB200/GB300 NVL72 这类整机柜形态里，Grace CPU 与 Blackwell GPU 之间的 NVLink-C2C 带宽远高于传统 PCIe，使权重卸载的可行性显著提升，但跨节点卸载仍受限于 fabric 带宽。因此卸载策略应按拓扑分层：同封装内 C2C 卸载可行，跨节点卸载只在权重账极大且批极小时考虑。</p>\n<p>另一个隐性代价是功耗：频繁的 host-device 传输与 GPU 空闲等待会拉低能效，在 SLO 以每瓦吞吐衡量时，卸载未必划算。卸载的收益要用端到端每步延迟与能效两个指标同时评估，不能只看显存峰值下降。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-24\">二十四 · 带宽瓶颈在哪：HBM3e 容量与带宽的复算</h3>\n<p>DiT 推理的带宽瓶颈随 <em>S</em> 变化而转移。小 <em>S</em> 时，每步的主要流量是权重读取（每层权重被所有 token 共享，读取一次），带宽压力来自权重账，此时批处理摊薄权重读取最有效。大 <em>S</em> 时，注意力分块导致值矩阵被重复读取，流量与 <em>S</em>·<em>B<sub>k</sub></em> 相关的重复次数成正比，带宽压力转向激活。判断转折点的方法是算算术强度：每字节 HBM 流量对应的 FLOPs，若低于机器峰值算力与带宽之比，就是带宽受限。</p>\n<div class=\"formula\">$$\\text{ArithmeticIntensity}=\\frac{\\text{FLOPs per step}}{\\text{Bytes per step}},\\quad \\text{ridge}=\\frac{\\text{Peak FLOPs}}{\\text{HBM Bandwidth}}$$</div>\n<p>HBM3e 的容量账要按三本账分别算。以单卡容量为上限，权重账按精度折算后占一部分，激活账按 <em>B</em>·<em>S</em>·<em>d</em> 与 <em>B</em>·<em>S</em>² 两项估算，跨步缓存按复用深度估算，三者之和加框架缓冲必须小于容量。容量约束直接决定最大批大小：解出满足 <em>M<sub>peak</sub></em> ≤ 容量的最大 <em>B</em>，就是该 <em>S</em> 下的批上限。带宽约束则决定这个批能否跑满算力：若算术强度低于 ridge，增大批只增加流量不增加吞吐。</p>\n<p>具体例子：一个中等宽度、中等深度的 DiT，在中等分辨率、中等 patch 下 <em>S</em> 为数千量级，注意力项 <em>B</em>·<em>S</em>² 在 <em>B</em> 稍大时即成为峰值主项；此时把 <em>B</em> 翻倍，激活账近似翻倍，而权重账不变，容量约束先于带宽约束生效。反过来，若把 patch 调大使 <em>S</em> 减半，注意力项降为四分之一，容量释放出的空间可用于增大 <em>B</em>，但每个 token 的感受野变大、质量可能变化，需与质量缩放关系联合评估。这正是论文以 Gflops 为统一尺度做容量规划的意义：patch 与宽度、深度的组合改变的是 <em>S</em> 与 <em>d</em>，而显存账对二者的敏感度不同。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随什么增长</th><th>主要压力</th><th>优化手段</th></tr></thead><tbody><tr><td>权重</td><td><em>N</em>·<em>d</em>²</td><td>容量、权重带宽</td><td>FP8/FP4、批摊薄、C2C 卸载</td></tr><tr><td>注意力激活</td><td><em>B</em>·<em>S</em>²</td><td>容量、HBM 带宽</td><td>分块、分页、FP8 分块缩放</td></tr><tr><td>MLP 激活</td><td><em>B</em>·<em>S</em>·<em>d</em></td><td>HBM 带宽</td><td>算子融合、FP8</td></tr><tr><td>跨步缓存</td><td><em>N<sub>reuse</sub></em></td><td>容量</td><td>阈值控制、host 卸载</td></tr><tr><td>条件嵌入</td><td><em>N</em>·<em>d</em></td><td>可忽略</td><td>预计算常驻</td></tr></tbody></table>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-25\">二十五 · 一个可复算的显存预算流程</h3>\n<p>把上述账本落成可执行流程，分四步。第一步定形状：由分辨率与 patch 尺寸得 <em>S</em>，由模型配置得 <em>d</em>、<em>N</em>、头数与 MLP 扩张比。第二步定精度：权重与激活的每元素字节数，注意力分数是否单独提精度。第三步算三项：权重项、激活项（注意力 + MLP）、缓存项，相加得 <em>M<sub>peak</sub></em>。第四步解约束：令 <em>M<sub>peak</sub></em> ≤ 可用容量，解出最大 <em>B</em>；再用算术强度判断该 <em>B</em> 是否带宽受限，若受限则减小 <em>B</em> 或改分块尺寸。</p>\n<p>流程中的关键判断是注意力项与权重项谁主导。若注意力项主导，优先做分块与分页，把 <em>S</em>² 的物化降到 <em>S</em>·<em>B<sub>k</sub></em>，再考虑精度压缩；若权重项主导，优先做权重量化与批摊薄。两者都主导时（中等 <em>S</em>、中等 <em>B</em>），需要联合调整 patch 与批，因为 patch 改变 <em>S</em> 会同时改变两项的相对比例。这个联合调整正是容量规划的核心：不是单独最大化某一项，而是在容量与带宽双约束下找可行域。</p>\n<p>最后落在工程判断上：DiT 的显存预算不是一次性算完的静态表，而是随请求形态（分辨率、帧数、批）变化的可行域。调度器需要把 <em>S</em> 与 <em>B</em> 作为一等参数纳入准入控制，按块池余量与带宽余量决定接纳与否，而不是按固定最大长度预留。跨步复用与卸载作为可选杠杆，只在容量或带宽成为硬约束时启用，并以其对采样质量的近似误差为代价上限。这样，显存账本从纸面公式变成每步可执行的准入与调度依据。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-26\">二十六 · DiT 显存账本的失效边界：token 平方项与固定步数循环</h3>\n\n<p>DiT 的显存账本不能按 U-Net 的“层数×通道”线性外推，因为其峰值项是每步注意力矩阵 <span class=\"formula-inline\">$$A\\in\\mathbb{R}^{B\\times H\\times S\\times S}$$</span>，其中 S 为 patchify 后的 token 数、H 为头数。S 由分辨率与 patch 尺寸共同决定，patch 减半即 S 翻四倍，注意力激活随之翻十六倍；而权重与 MLP 激活只随 d²·L 线性增长。这意味着在小 patch、高分辨率配置下，账本的主导项从权重切换到注意力，容量规划若仍以参数量为锚就会系统性低估峰值。更关键的是扩散采样是固定步数循环，每步重复 patchify、N 层前向与 unpatchify，激活不跨步保留却逐步重新分配，步数增加使带宽压力线性累积而非显存峰值线性累积——这两者的区别决定了优化方向是“省容量”还是“省搬运”。</p>\n\n<p>可复算的预算应按三项分列：权重 <span class=\"formula-inline\">$$M_w \\approx P\\cdot b_w$$</span>、注意力激活 <span class=\"formula-inline\">$$M_a \\approx B\\cdot H\\cdot S^2\\cdot b_a\\cdot N_{\\text{live}}$$</span>（<span class=\"formula-inline\">$$N_{\\text{live}}$$</span> 为同时驻留的层数，取决于是否做层间复用）、以及条件嵌入与采样器状态这类与 B 成正比的常驻项。以 b_w 取 FP8、b_a 取 FP16 为例，若 S 增大到使 <span class=\"formula-inline\">$$S^2 b_a$$</span> 超过单层权重字节数，则批大小必须让位于序列长度：先降 B 再考虑分块，而不是反过来。表中给出三种配置的相对关系，用于判断账本在哪一项翻转。</p>\n\n<table class=\"mini\"><thead><tr><th>配置变化</th><th>权重项</th><th>注意力项</th><th>系统代价</th></tr></thead><tbody><tr><td>patch 减半</td><td>不变</td><td>×16</td><td>显存峰值主导项翻转，批大小须下调</td></tr><tr><td>批大小翻倍</td><td>不变（可摊薄读取）</td><td>×2</td><td>吞吐上升但显存峰值线性上升</td></tr><tr><td>步数翻倍</td><td>不变</td><td>峰值不变</td><td>HBM 带宽占用线性累积，时延翻倍</td></tr></tbody></table>\n\n<p>失效条件有三类。其一，把 Gflops 缩放结论外推到长视频：Gflops 公式 <span class=\"formula-inline\">$$\\approx k\\cdot N\\cdot d^2\\cdot L$$</span> 不含 S² 项，而长视频恰恰使 S 爆炸，按 Gflops 选型会得到“算力够、显存不够”的错配。其二，对注意力激活直接做 FP8 量化而未验证数值稳定性：注意力 logits 的动态范围与 softmax 前的缩放对量化误差敏感，采样质量下降不会在单步指标上暴露，而是在多步累积中显现。其三，按图像分辨率标定的批大小直接搬到视频分块推理：分块间的重叠区域使有效 S 大于名义值，显存峰值超出预期。工程判断是：DiT 的容量规划必须以 S 与 B 的联合约束为第一约束，权重精度与层间激活复用是第二位的调节手段；在 token 平方项成为主导后，分块与重叠策略的收益来自把 S 压回线性区，而非来自量化本身。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-27\">二十七 · 从“固定步数循环”到可调度请求</h3>\n<p>DiT的采样过程是一个固定步数的去噪循环：每步对潜变量做patchify、N层Transformer前向、unpatchify，再交给采样器更新。这个循环在单请求视角下是串行且不可中断的，但一旦部署成服务，它就必须被拆成可调度的单元——否则GPU只能被一个请求独占，权重读取无法摊薄，吞吐被步数直接锁死。调度层的第一个判断是：把“请求”当作调度粒度，还是把“步”当作调度粒度。前者实现简单，后者才能做连续批处理。在DiT里，步与步之间没有自回归KV依赖，潜变量是唯一的跨步状态，这让“按步调度”成为可能：一个请求在第k步完成后可以暂时让出执行槽，另一个请求的第j步可以插入，只要两者的token序列长度与激活显存能共存于同一批次。</p>\n<p>代价在于激活显存的叠加方式。设批内有$B$个请求，序列长度为$S$，注意力矩阵规模为$O(BS^2)$，MLP激活为$O(BSd)$。连续批处理把不同请求的步拼进同一批次，摊薄了每步的权重读取带宽，但注意力激活随$B$线性上升，且不同请求的$S$可能不同，导致批次内出现padding或变长注意力的额外开销。工程判断是：当$S$较大（高分辨率、长视频分块）时，批大小必须压到很小，连续批处理的收益主要来自权重摊薄而非激活复用；当$S$较小（低分辨率图像）时，批可以放大，吞吐提升明显。这个取舍直接决定了调度器是按“显存预算”还是按“token预算”做准入。</p>\n<div class=\"formula\">$$\\text{每步激活}\\approx B\\cdot S^2\\cdot h + B\\cdot S\\cdot d\\cdot L,\\quad \\text{权重读取}\\approx \\frac{W}{B}$$</div>\n<p>具体例子：一个图像类条件生成服务，潜特征经patchify后序列长度固定，批大小受注意力激活峰值约束。调度器若按请求粒度整段执行，则在某请求的采样步数未走完前，新请求只能排队；若按步粒度做连续批处理，新请求可以在当前步结束后插入，权重读取被更多请求共享，但每步的注意力激活峰值随批内请求数上升，需要准入控制。论文未给出批调度与SLO数据，这一层参数必须在部署时实测。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-28\">二十八 · Chunked prefill：把长序列的首步切开</h3>\n<p>DiT没有自回归prefill，但有一个等价物：采样循环的第一次前向必须处理完整token序列，且条件注入（adaLN-Zero的逐块scale/shift）在这一步就要生效。当序列很长时，首步的注意力矩阵会形成显存尖峰，后续步虽然计算量相同，但显存峰值已被首步锁定。chunked prefill的思路是把长序列按token维切块，分多次前向完成首步的注意力计算，块间通过重叠或分块注意力拼接结果。对DiT而言，全局注意力不允许简单切块后独立计算——切块会丢失跨块注意力，必须用分块注意力或重叠窗口来近似，代价是额外的通信或重复计算。</p>\n<p>更实际的做法是把chunked prefill用在“分块推理”上：高分辨率或长视频场景下，潜特征本身就被切成多个空间块，每块独立patchify成token序列，块间用重叠区域保证边界一致性。调度层把每个块当作一个子请求，按步推进，块间重叠区域的激活需要保留到相邻块完成，形成额外的显存驻留。代价是：分块数增加时，重叠区域的重复计算使有效Gflops上升，且块间同步点增多，尾延迟被最慢的块拖长。工程上要把块大小选在“单块激活不超过显存预算”与“重叠比例不超过可接受重复计算”之间。</p>\n<p>具体例子：视频扩散按时间维分块，每块包含若干帧的潜特征，块间保留重叠帧。调度器把每块作为独立请求推进采样步，重叠帧的激活在相邻块间共享，减少重复前向。若块太小，重叠比例上升，权重读取被更多块摊薄但重复计算增加；若块太大，单块注意力激活超出预算，chunked prefill退化为不可调度。论文的全局注意力结构决定了这个块大小不能任意缩小，必须在注意力形状可分析的范围内选取。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-29\">二十九 · 优先级与抢占：尾延迟从哪里来</h3>\n<p>扩散采样的延迟分布不是单峰的：步数固定，但每步的计算量随token序列长度与批内共存请求变化。尾延迟的主要来源不是单步计算慢，而是排队与抢占。当一个长序列请求与多个短序列请求共存时，长请求的每步占用更多显存与带宽，调度器若按FIFO执行，短请求被长请求的步阻塞，尾延迟被拉长。优先级调度的做法是给短请求更高优先级，让它们在长请求的步间插入；抢占则允许在显存不足时把长请求的中间状态换出，腾出空间给高优先级请求。</p>\n<p>DiT的可抢占性来自其状态很小：跨步状态只有潜变量与条件嵌入，没有自回归KV。换出代价是潜变量的显存拷贝，换入时需要重新patchify。这与LLM的KV cache抢占不同——后者换出的是随序列长度增长的KV，代价高得多。因此DiT的抢占粒度可以更细：按步抢占，甚至按块抢占。代价是换入换出的带宽开销，若抢占频繁，PCIe或NVLink上的潜变量搬运会成为新的瓶颈。工程判断是：抢占阈值应设在“换出带宽开销小于排队延迟增量”的位置，而不是简单地按显存水位触发。</p>\n<table class=\"mini\"><thead><tr><th>调度策略</th><th>尾延迟来源</th><th>主要代价</th><th>适用场景</th></tr></thead><tbody><tr><td>FIFO整请求</td><td>长请求阻塞短请求</td><td>权重读取无法摊薄</td><td>低负载、同质请求</td></tr><tr><td>按步连续批处理</td><td>批内最长序列决定步时</td><td>注意力激活随批上升</td><td>短序列、高吞吐</td></tr><tr><td>优先级＋按步抢占</td><td>换入换出带宽</td><td>潜变量搬运开销</td><td>混合长度、SLO分级</td></tr><tr><td>分离式预填/解码</td><td>跨节点传输延迟</td><td>潜变量与条件传输</td><td>长序列、多卡池</td></tr></tbody></table>\n<p>具体例子：一个服务同时接收低分辨率图像请求与高分辨率视频分块请求。若按FIFO，视频块的长序列步会占满显存，图像请求排队，尾延迟超标。按步抢占后，图像请求在视频块的步间插入，视频块的潜变量被换出到主机内存，换入时重新patchify。尾延迟被压到图像请求的步时量级，代价是视频块的换出带宽与重新patchify的计算。这个取舍在论文的部署语境中未被量化，但机制上成立。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-30\">三十 · 分离式预填/解码：把首步与后续步分开</h3>\n<p>分离式预填/解码在LLM里是把prefill与decode放到不同节点，因为两者的计算形态不同：prefill是计算密集的大矩阵乘，decode是带宽密集的小批次前向。DiT的对应物是“首步”与“后续步”：首步要处理完整token序列并建立条件注入的逐块scale/shift，后续步重复相同的计算但潜变量已更新。两者的计算形态其实相同——DiT每步都是完整序列前向，没有LLM那种decode阶段的序列长度缩减。因此分离式部署在DiT里的收益不在计算形态差异，而在资源池化：把首步放到一个高算力池，后续步放到一个高带宽池，或者把不同请求的步分配到不同卡上，避免单卡显存被长序列锁死。</p>\n<p>代价是跨节点传输。DiT的跨步状态是潜变量，大小与token序列成正比，传输量远小于LLM的KV cache，但传输延迟会叠加到每步的临界路径上。若每步都要跨节点同步，步时被网络延迟主导，吞吐下降。工程判断是：分离式部署只在步数较多、单步计算量足够大时才划算，且传输应与计算重叠——在上一卡计算当前步的同时，把下一步的潜变量预传到下一卡。论文未给出分离式部署实验，这一层的参数需要按潜变量大小与链路带宽实测。</p>\n<div class=\"formula\">$$\\text{步时}\\approx \\max(\\text{计算},\\ \\text{传输})+\\text{同步开销},\\quad \\text{传输量}\\propto S\\cdot d$$</div>\n<p>具体例子：多卡池部署，请求A的首步在卡0完成，后续步轮转到卡1、卡2。潜变量在卡间传输，条件嵌入随请求走。若传输与计算重叠，步时接近单卡计算时间；若不重叠，步时被传输延迟拉长，分离式部署反而增加尾延迟。调度器需要把传输预算纳入准入判断，而不是只看单卡显存。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-31\">三十一 · 时延与吞吐的联合规划</h3>\n<p>DiT的吞吐提升来自批处理摊薄权重读取，时延则由单请求的步数与每步计算量决定。两者的矛盾点在注意力激活：批大小上升时，权重读取的摊薄收益递减，而注意力激活的显存占用线性上升，最终触发准入拒绝或抢占。规划时要把“每步激活峰值”作为第一约束，把“权重读取摊薄”作为第二目标。设单请求的序列长度为$S$，批大小为$B$，显存预算为$M$，则准入条件近似为$B\\cdot S^2\\cdot h\\le M$，在这个约束下最大化$B$以摊薄权重。当$S$很大时，$B$被迫为1，吞吐只能靠步间流水与分离式部署提升，而不是靠批。</p>\n<p>尾延迟的压制要区分两种来源：排队延迟与执行延迟。排队延迟由调度策略决定，执行延迟由批内最长序列与抢占换入换出决定。工程上常用的做法是给请求分级：短序列请求走高优先级、小批快速通道，长序列请求走低优先级、按步推进通道，两者共享权重读取但不共享显存峰值。代价是调度器复杂度上升，且分级阈值需要按实测的步时分布来定。论文的Gflops缩放关系可用于容量规划：给定目标质量对应的Gflops档位，反推token序列长度与批大小的可行域，再把可行域交给调度器做准入。</p>\n<p>具体例子：按Gflops档位选定模型宽度与patch尺寸后，token序列长度确定，单请求每步激活峰值可估。调度器据此设定批大小上限，并在负载上升时优先拒绝长序列请求而非降低批大小，因为降低批大小会同时损失吞吐与时延。这个判断的依据是：长序列请求的每步激活占用高，拒绝它的边际吞吐损失小于让所有请求降批的损失。论文未给出SLO数据，但机制上这个取舍是可分析的。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-32\">三十二 · 调度层的可观测项</h3>\n<p>调度与批处理的正确性不能只靠吞吐数字判断，需要可观测项来定位瓶颈。第一项是每步注意力激活峰值，它决定准入是否触发；第二项是批内序列长度的分布，它决定步时是否被最长序列拖长；第三项是抢占次数与换出带宽，它决定尾延迟是否被换入换出主导；第四项是权重读取的摊薄率，即实际批大小与显存允许的最大批大小之比。这四项共同构成调度层的反馈回路：激活峰值上升时收紧准入，序列长度分布偏斜时调整优先级，抢占频繁时提高换出阈值或改分离式部署，摊薄率低时说明批大小被其他约束锁死，需要检查是否该用分块或分离式。</p>\n<p>具体例子：监控发现摊薄率长期低于显存允许的上限，而激活峰值未触顶，说明批大小被调度策略而非显存限制——可能是FIFO整请求执行导致批无法拼满。改为按步连续批处理后，摊薄率上升，吞吐提升，但激活峰值随之上升，需要重新校准准入。这个回路在论文的部署语境中未被给出，但DiT的token序列与注意力形状使这些量都可按公式估算，不需要黑盒调参。调度层的工程判断最终落在：把激活峰值当作硬约束，把摊薄率当作优化目标，把抢占与分离式当作尾延迟的兜底手段，三者按实测步时分布联合调整。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-33\">三十三 · 从单卡到多卡：DiT 的切分维度与通信原语</h3>\n<p>DiT 的推理图是“固定步数循环 × N 层 Transformer 块”，每层含一次全局多头自注意力与一次 MLP。要把这张图摊到多卡上，只有四条正交的切分轴：数据并行（DP）复制权重、切分批次；张量并行（TP）切分每层的权重矩阵与注意力头；专家并行（EP）在 MoE 化的 FFN 上切分专家；流水并行（PP）按层段切分并把微批沿深度方向排成流水。四条轴对应的通信原语不同：DP 的梯度同步在推理中退化为无操作，真正付出的是权重广播与请求分发；TP 在每层注意力与 MLP 之后各做一次 All-Reduce（或 Reduce-Scatter + All-Gather 的等价形式）；EP 在 token 路由处做 All-to-All；PP 在层段边界做点对点激活传递。DiT 的注意力是全局的，token 序列在序列维上天然可切，但切分后每个 rank 只持有部分 token 的 Q/K/V，注意力输出需要按头或按序列维重组，这一步就是 TP 在注意力层的通信代价来源。</p>\n<p>用公式刻画单层 TP 的通信量：设隐藏维为 d、序列长度为 S、批大小为 B、TP 度为 t，则每层注意力后的一次 All-Reduce 需搬运的字节数约为</p>\n<div class=\"formula\">$$V_{\\text{AR}} \\approx 2\\cdot(t-1)/t\\cdot B\\cdot S\\cdot d\\cdot b$$</div>\n<p>其中 b 为每元素字节数（FP8 为 1、BF16 为 2）。系数 2 来自 All-Reduce 的 reduce-scatter 与 all-gather 两段。MLP 后还有一次同规模 All-Reduce，因此每层通信量是上式的两倍。把 N 层与采样步数 T 乘进去，单个请求的总通信量为 <span>2·N·T·V_AR</span>。这个式子的关键含义是：通信量与 token 数 S 成正比，而计算量中注意力部分与 S² 成正比、MLP 部分与 S·d² 成正比。于是存在一个交叉点——当 S 足够大时，计算增长快于通信，TP 的通信占比下降；当 S 较小（高 patch 压缩率、低分辨率）时，通信占比上升，TP 度越大越不划算。</p>\n<p>具体例子：以 DiT 的 patchify 机制为例，潜特征分辨率提高一档或 patch 尺寸减半，token 数 S 翻倍，注意力矩阵规模变为四倍，而每层 All-Reduce 的字节数只翻倍。这意味着在长序列场景下，TP 的通信瓶颈反而被计算掩盖；真正被通信卡住的是短序列、大批次、高 TP 度的配置——此时每层两次 All-Reduce 的固定延迟（与消息大小弱相关、与 rank 数强相关）成为每步循环的刚性开销。推理系统代价上，这表现为每步延迟中通信等待占比上升、GPU 利用率下降，而显存并未因此缓解。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-34\">三十四 · NVLink 5 与 NVSwitch：把 All-Reduce 压进交换结构</h3>\n<p>Blackwell 世代的 GB200/GB300 NVL72 机柜把 72 个 GPU 通过 NVLink 5 与 NVSwitch 连成单一大带宽域，其意义不在于峰值带宽数字本身，而在于让 TP 与 EP 的通信从“跨节点 RDMA”退化为“机柜内交换”。对 DiT 推理而言，这改变了两件事：其一，TP 度可以开到 8 甚至更大而不必担心跨节点跳数带来的延迟抖动，因为 All-Reduce 的每一跳都落在 NVSwitch 上；其二，EP 的 All-to-All 可以在同一域内完成，token 路由的尾延迟可控。NVSwitch 的全互联拓扑使 All-Reduce 的算法选择从环形（ring）转向递归倍增或 NVLS（NVLink SHARP）类的交换机内归约，后者把归约操作下沉到交换芯片，减少了数据在端点间的往返次数。</p>\n<p>代价侧的判断是：NVLink 域内带宽充裕，但 All-Reduce 的延迟仍随 rank 数对数增长，且交换机内归约要求数据格式与归约类型被硬件支持。若在注意力激活上做 FP8 量化后再 All-Reduce，需要确认归约是否在 FP8 上直接进行还是先升到 BF16——后者会使有效通信字节数翻倍，抵消量化收益。这是一个具体的工程取舍：量化省下的是计算与显存，通信侧可能因归约精度要求而回吐。</p>\n<p>具体例子：NVL72 内做 8 路 TP 的 DiT 推理，每层两次 All-Reduce 落在 NVSwitch 上，单次消息为 B·S·d 个元素；若 B·S·d 较小（短序列、小批），延迟由固定跳数与协议开销主导，此时把 TP 度从 8 降到 4、把省下的卡用于 DP 提升批吞吐，往往比继续加 TP 更划算。这就是“通信什么时候成为瓶颈”的第一个判据：当单次消息小到无法摊薄固定延迟时，增加并行度是负收益。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-35\">三十五 · All-to-All 与 EP：MoE 化 FFN 的 token 路由代价</h3>\n<p>DiT 的标准块是稠密 MLP，本身不需要 All-to-All。但把 FFN 换成 MoE 是视频扩散扩容的常见路径，此时 EP 引入 All-to-All：每个 rank 上的 token 按路由结果被发往持有对应专家的 rank，专家计算后再发回。All-to-All 的通信量与 token 数、路由分散度（每个 token 被送往多少个 rank）成正比，且是双向的——去程与回程各一次。与 All-Reduce 不同，All-to-All 是“非对称”的：每个 rank 发出的数据量与收到的数据量取决于路由分布，负载不均会直接转化为等待。</p>\n<p>伪代码层面的路由代价可以写成：对每个 token，计算 top-k 专家索引，按目标 rank 分组打包，执行 All-to-All，本地专家前向，再执行反向 All-to-All 并按原索引散射回 token 位置。关键开销在打包与散射的索引操作，以及 All-to-All 的尾延迟由最慢的那个 rank 决定。容量因子（capacity factor）设得越小，丢弃或溢出的 token 越多，通信量越小但质量受损；设得越大，通信量与显存缓冲越大。这是一个显式的质量—通信权衡旋钮。</p>\n<p>推理系统代价上，EP 的显存收益是实的：专家权重按 rank 切分，单卡权重显存下降；但激活缓冲需要为 All-to-All 预留收发缓冲，缓冲大小与 B·S·k 成正比。对 DiT 的固定步数循环，这意味着每步都有两次 All-to-All 的固定开销，步数越多累积越明显。具体例子：一个 8 专家、top-2 路由的 MoE-FFN，在 8 路 EP 下每个 token 平均被送往 2 个 rank，去程与回程各搬运 k·d 个元素；若批内 token 路由高度集中到少数专家（条件类别导致的路由偏斜），则部分 rank 空转、All-to-All 退化为少数链路的热点，尾延迟被拉长。判断 EP 是否值得，要看专家负载是否可均衡，而不是只看权重显存省了多少。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-36\">三十六 · PP 与 DP：流水气泡与权重广播</h3>\n<p>PP 把 N 层切成若干段，微批沿段间流动。DiT 的采样是固定步数循环，每步都要完整走一遍 N 层，因此 PP 的气泡在每步开始时重复出现：第一段在算、后续段在等。要摊薄气泡，需要把批切成多个微批做流水填充，但微批数受注意力激活显存限制——这与前文批调度的结论一致，此处只指出 PP 与批大小的耦合：微批越多，气泡占比越低，但每卡的激活峰值越高。PP 的通信是点对点激活传递，量级为 B·S·d，比 TP 的 All-Reduce 小，但延迟敏感，因为段间是串行依赖。</p>\n<p>DP 在推理中不涉及梯度同步，其通信代价是权重加载与请求分发：每个 DP rank 持有完整权重副本，权重显存不随 DP 度下降，这是 DP 与 TP/EP 的根本区别。对 DiT 这种权重占显存可观、激活随 S² 增长的骨干，DP 扩的是吞吐而不是显存容量；当激活显存而非权重显存成为瓶颈时，DP 无助益。权重广播的代价出现在扩缩容与热更新时，量级为整个权重集，属于低频但高带宽事件。</p>\n<p>具体例子：把 DiT 的 N 层均分到 4 段 PP、每段若干层，单请求延迟约等于四段串行之和加上三次段间传递；若批内只有单请求，气泡无法摊薄，PP 的延迟高于单卡。只有当并发请求足够多、微批能填满流水时，PP 才换回吞吐。这是“通信什么时候成为瓶颈”的第二个判据：串行依赖型的通信（PP 段间）在低并发下无法被计算掩盖。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-37\">三十七 · NIXL 传输与分离式部署：预填/解码拆分的搬运账</h3>\n<p>分离式预填/解码把条件编码与去噪循环的前段放在一组卡、后段或解码放在另一组卡，中间需要搬运潜变量、条件嵌入与激活。NIXL 这类传输层的作用是把点对点搬运从应用层协议里剥离出来，直接走 RDMA 或 NVLink，降低拷贝与同步开销。对 DiT 而言，可搬运的对象是每步的潜变量 z_t（尺寸为潜空间分辨率，远小于 token 序列激活）与条件嵌入（adaLN-Zero 产生的逐块 scale/shift，尺寸为 N·d 量级）。注意 DiT 没有自回归 KV cache，跨步复用的是激活与条件嵌入，因此分离式部署的搬运量比 LLM 解码小得多，瓶颈不在带宽而在同步延迟与流水编排。</p>\n<p>代价判断：若把去噪循环切成两段，每步都要在段边界同步一次，步数 T 乘以同步次数就是总延迟中的固定项。搬运 z_t 的字节数为潜变量元素数乘以字节数，量级远小于注意力激活，因此分离式部署对 DiT 的收益主要来自资源异构分配（把显存密集段与计算密集段分开放），而不是带宽节省。NIXL 在这里的价值是让同步延迟可预测，而不是提升吞吐。</p>\n<p>具体例子：条件嵌入在采样开始时算一次即可复用整个循环，把它放在预填侧并只搬运一次，而不是每步重算或重传，能省掉 N·d 量级的重复搬运；反之若每步都重新注入条件并跨段传递，同步次数翻倍而搬运量不变，延迟白白增加。这是编排层面的具体机制，而非带宽问题。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-38\">三十八 · 瓶颈判据：什么时候通信压过计算</h3>\n<p>把上面的量级放在一起，可以得到三条可操作的判据。第一，比较每层通信时间与计算时间：TP 的 All-Reduce 时间为 <span>V_AR / BW</span> 加上固定延迟，计算时间为该层 FLOPs 除以算力；当 S 小、d 大、TP 度高时，通信占比上升。第二，比较串行依赖通信与可掩盖通信：PP 段间与分离式同步是串行的，低并发下无法掩盖；TP 的 All-Reduce 在层内可与下一层的计算部分重叠（若框架做了通信—计算重叠），属于可掩盖类。第三，比较通信节省的显存与通信付出的延迟：EP 省权重显存但付 All-to-All 尾延迟，TP 省权重与激活但付每层两次 All-Reduce，DP 不省显存只扩吞吐。</p>\n<p>对 DiT 的具体落点：全局注意力使激活随 S² 增长，因此长序列、高分辨率场景下 TP 切分序列维是缓解显存的主手段，此时通信被大计算量掩盖，TP 是正收益；短序列、大批次场景下注意力计算相对小，TP 的固定延迟占比高，应优先用 DP 扩吞吐、用较小的 TP 度控制延迟。MoE 化 FFN 的 EP 是否启用，取决于路由负载能否均衡，否则 All-to-All 尾延迟会吞掉权重显存收益。PP 只在并发足够、微批能填满流水时启用。</p>\n<p>工程判断落在具体机制上：在 Blackwell 机柜内，NVLink 5 与 NVSwitch 把 TP/EP 的通信压到域内，使“通信是否成为瓶颈”从带宽问题转为延迟与编排问题；对 DiT 这种固定步数、无 KV cache、激活随 token 平方增长的骨干，最容易被通信卡住的不是大序列而是小消息高频同步——每层两次 All-Reduce、每步一次段间同步，这些固定项在步数循环里被反复计费。把条件嵌入的一次性搬运与逐块 scale/shift 的复用做对，比单纯提高 TP 度更能压住每步延迟。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-39\">三十九 · 精度塌陷：从“能跑”到“跑对”的断层</h3>\n<p>DiT的推理图在数值上是脆弱的：每步patchify后的token序列进入N层Transformer块，全局自注意力在token维上做softmax，adaLN-Zero产生的逐块scale/shift又直接乘在归一化后的激活上。任何一处量化误差都会沿层间放大，而不是被卷积的局部感受野吸收。典型塌陷路径是：把注意力激活压到FP8后，softmax分母的动态范围被截断，注意力权重在低亮度token上趋近均匀，采样轨迹偏离，表现为生成结果“结构还在、纹理糊掉”——这类失败不会抛异常，只会让FID悄悄劣化。</p>\n<p>诊断要落到具体张量上。对每层注意力输出做逐token的L2范数统计，与FP16基线对比，若某层范数分布的尾部被削平，说明该层不适合低精度。工程上常用的判据是逐层信噪比：</p>\n<div class=\"formula\">$$\\mathrm{SNR}_l = 10\\log_{10}\\frac{\\lVert A_l^{\\mathrm{fp16}}\\rVert_2^2}{\\lVert A_l^{\\mathrm{fp16}}-A_l^{\\mathrm{low}}\\rVert_2^2}$$</div>\n<p>当某一层SNR低于阈值而其余层正常，就把该层回退到FP16或BF16，其余层保留NVFP4/FP8，形成混合精度白名单。代价是显存与带宽：单层回退会让该层权重读取翻倍，若回退层集中在注意力投影上，每步带宽上升，采样延迟随之增加；但相比整网回退，白名单把代价限制在少数层。例子：一个以patch=2、分辨率较高配置的DiT，注意力QKV投影是塌陷高发层，而MLP在NVFP4下稳定，于是只回退QKV，保留MLP低精度，显存峰值可控而质量恢复。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-40\">四十 · OOM：token平方项与批大小的耦合</h3>\n<p>DiT的显存峰值不在权重，而在每步的注意力矩阵。token数$T$由分辨率与patch尺寸决定，注意力激活规模随$T^2$增长，批大小$B$再线性乘上去。容量估算不能只看单请求：</p>\n<div class=\"formula\">$$M_{\\mathrm{peak}} \\approx B\\cdot N\\cdot\\left(c_1 T^2 + c_2 T d\\right) + M_{\\mathrm{weights}} + M_{\\mathrm{decode}}$$</div>\n<p>其中$c_1T^2$是注意力分数与softmax中间量，$c_2Td$是MLP激活。OOM的典型触发不是稳态，而是解码阶段的VAE解码峰值与最后几步的激活叠加。诊断顺序：先看OOM发生在去噪循环内还是unpatchify/解码阶段；前者调批大小或分块，后者调解码分块策略。</p>\n<p>失败模式很具体：按图像分辨率标定的批大小直接搬到视频分块推理，token序列变长但批大小没降，注意力激活把显存打爆。正确做法是把批大小当作token预算的函数而非固定值，按$B\\cdot T^2$设上限，长序列场景退化为小批甚至单请求加序列分块。代价是吞吐：批大小减半，权重读取摊薄效果变差，每token的有效带宽成本上升；但这是避免OOM的必要折中。监控上要在每步记录注意力激活峰值，而不是只记录进程总显存，否则定位不到是哪一步、哪一层撑爆的。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-41\">四十一 · 批抖动：摊薄收益被激活增长吃掉</h3>\n<p>批处理在DiT上不是单调收益。权重读取随批大小摊薄，但注意力激活随批线性上升，两者在某个批大小处交叉，吞吐曲线出现平台甚至回落。抖动表现为：批大小从$B$加到$B+1$，吞吐不升反降，延迟方差变大。根因是显存带宽饱和后，调度器开始在请求间争抢，连续批处理的填充与排出节奏被打乱。</p>\n<p>定位方法是画吞吐-批大小曲线并同时记录每步带宽利用率。若带宽利用率在交叉点附近触顶，说明已到带宽墙，继续加批只会增加排队延迟。工程判断是取曲线平台起点作为生产批大小，并留出余量给尾请求。例子：固定步数采样下，批大小增加使每步MLP的权重读取摊薄，但注意力矩阵的写回带宽同步上升，当后者主导时，单步时间不再下降；此时把批大小回退一档，尾延迟明显收敛而总吞吐损失有限。</p>\n<p>抖动还会伪装成“随机变慢”：同一批大小下，不同请求的token数不同（分辨率或分块不同），连续批处理把长短请求混在一批，长请求拉高整批的注意力激活，短请求被迫等待。解法是按token预算而非请求数做批组装，把长序列请求单独成批，牺牲少量摊薄换取延迟可预测。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-42\">四十二 · 尾延迟：固定步数循环里的长尾</h3>\n<p>扩散采样是固定步数循环，每步都要走完整的patchify、N层Transformer、unpatchify。尾延迟的来源不是单步慢，而是某几步的激活峰值触发显存回收或分块切换，导致该步耗时突增。adaLN-Zero的条件注入让每步的计算图一致，但条件嵌入的读取与scale/shift生成在批内不同请求间可能有差异，混批时最慢请求决定整批步进。</p>\n<p>监控要按步打点：记录每步的耗时分布，找出P99步与中位步的差距。若差距集中在去噪循环的前几步或最后几步，通常是激活峰值与解码衔接问题；若均匀分布，则是带宽饱和。回滚策略上，尾延迟超标时优先降批大小或把长请求拆出，而不是降精度——降精度会引入第一节的塌陷风险，且不一定改善尾延迟。</p>\n<p>代价权衡很直接：为压尾延迟而减小批大小，吞吐下降；为保吞吐而混批，尾延迟上升。SLO规划要把这两者写成约束：给定尾延迟上限，反推可接受的最大批大小与最长token序列，再把超出预算的请求路由到独立队列。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-43\">四十三 · 静默降级：没有报错的劣化</h3>\n<p>最危险的失败模式是不报错的劣化。DiT推理中三类静默降级最常见：一是低精度注意力导致的采样轨迹偏移，输出仍能解码但质量下降；二是分块推理的重叠策略不足，块边界出现接缝，指标上看不出异常但人眼可见；三是批调度把请求排到错误的步进节奏，采样步数与条件错配，生成结果与提示不符。三者都不抛异常，只体现在质量指标或人工抽检上。</p>\n<p>监控要建立基线对照：定期用固定种子、固定条件的探针请求跑一遍，与FP16基线输出做感知距离或统计距离比对，偏离超过阈值就触发回滚。探针请求要覆盖不同token长度与批大小组合，因为降级往往只在特定形状下出现。回滚粒度要细：精度白名单按层回滚，分块策略按重叠参数回滚，批调度按队列配置回滚，避免一刀切回退到全FP16而丢掉全部吞吐收益。</p>\n<p>工程判断落在具体机制上：把“精度配置、分块重叠、批组装规则”三者做成可版本化的推理配置，每次变更都伴随探针基线的重跑；探针偏离与尾延迟超标作为两个独立回滚触发器，前者保质量，后者保SLO。这样静默降级不会靠人眼发现，而是靠固定探针在配置变更后第一时间暴露。</p>\n\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-44\">四十四 · 失效边界：当 token 平方项压过 Gflops 线性项</h3>\n<p>DiT 的容量规划容易落入一个陷阱：论文给出的 <span class=\"formula\">$$\\mathrm{Gflops}\\approx k\\cdot N\\cdot d^2\\cdot L$$</span> 是线性于层数、宽度与 token 数的，但采样推理的真实显存与带宽瓶颈并不在这条线上，而在每步注意力矩阵的 <span class=\"formula\">$$S^2$$</span> 项（S 为 token 序列长度）。把图像分辨率下的批大小经验直接搬到视频分块推理，是典型的静默降级起点：Gflops 估算仍在线性区间内，单步延迟看似可控，但注意力激活峰值已越过单卡上限，触发驱动层换页或框架的隐式重算，吞吐骤降而错误码不出现。诊断这类问题的第一原则是把监控指标从\"每步 Gflops 利用率\"改为\"每步注意力激活峰值 / 单卡可用显存\"的比值，并对 S 与批大小的乘积设硬阈值告警——因为激活随批大小线性上升、随 S 平方上升，二者的乘积才是真正的显存需求。一个具体例子：同一 DiT 配置在固定分辨率下批大小可开到某档位，切换到长视频分块后 token 数翻倍，注意力激活按四倍增长，原批大小必须下调到四分之一以下才能维持峰值不变，否则 OOM 会以\"解码阶段显存峰值\"的形式在采样循环末尾才暴露，定位成本极高。</p>\n<p>精度塌陷是第二类失效，且比 OOM 更隐蔽。adaLN-Zero 产生的逐块 scale/shift 直接参与归一化，条件嵌入的数值范围与注意力激活的分布耦合；在未做数值稳定性验证的情况下对注意力激活施加 FP8，量化误差会通过逐块调制放大，表现为采样结果\"能出图但语义漂移\"——类别条件不再生效、时间步语义模糊。这类失败不会抛异常，只能靠离线对照诊断：固定随机种子与条件，比较量化前后若干步的噪声预测张量范数与方向余弦，若余弦相似度在某层之后系统性跌落，即定位到该层调制路径的量化位宽不足。代价是诊断本身需要保留一份高精度参考路径，显存开销翻倍，因此应作为发布前的门禁而非线上常驻。工程判断是：权重可先量化，激活量化必须逐层做敏感性排序，adaLN-Zero 的调制分支优先保留高精度。</p>\n<p>批抖动与尾延迟来自扩散采样的固定步数循环结构。与自回归解码不同，DiT 每步都要重跑 patchify、N 层前向与 unpatchify，步数增加时激活显存与带宽线性累积，而批处理只能摊薄权重读取、无法摊薄注意力激活。连续批处理在扩散场景下并不天然成立：一个请求的采样步数固定，新请求只能在步边界插入，插入时机不均会造成批内 token 数波动，进而使每步注意力矩阵规模抖动，表现为 P99 延迟远高于均值。监控上应分别采集\"步级延迟分布\"与\"批内 token 数分布\"，两者的相关性一旦升高，说明调度器在跨步拼批时未对齐序列长度。缓解手段是按 token 数分桶排队、限制单批 token 总数上限，代价是低负载时桶内请求凑不满、GPU 利用率下降——这是尾延迟与吞吐之间的显式折中，必须在 SLO 里写明。</p>\n<p>回滚策略要按失效类型分层，而非统一回退到上一版本。显存类失效（OOM、换页）回滚的是批大小与分块重叠参数，模型权重不动；精度类失效回滚的是量化配置与调制分支位宽，需保留可复现的种子与条件集做灰度对比；调度类失效回滚的是拼批策略与桶边界。三类回滚的触发信号应来自不同监控通道：显存峰值比值、噪声预测余弦相似度、步级延迟 P99 与批内 token 方差。把三者混在一个健康度指标里，会导致精度塌陷被吞吐正常所掩盖——这正是静默降级最难定位的形态。可维护的做法是为每次配置变更记录一份\"推理指纹\"：固定种子下若干步的激活统计量与输出哈希，任何偏离指纹的上线都视为可疑，先降级到高精度路径再排查。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-45\">四十五 · 把“Gflops”当作唯一横轴时，口径就已经错了</h3>\n<p>DiT 论文的缩放结论建立在一个刻意收窄的横轴上：Gflops。公式写作 <span class=\"formula\">$$\\mathrm{Gflops}\\approx k\\cdot N\\cdot d^2\\cdot L$$</span> 其中 N 为层数、d 为宽度、L 为 token 序列长度。这个式子把宽度、深度、patch 尺寸三个自由度压缩成一个标量，好处是不同配置可以排在同一条曲线上比较质量；代价是它把注意力的二次项藏进了 k 里。工程读者必须意识到：当 L 翻倍时，MLP 部分线性增长，而注意力矩阵按 L² 增长，k 不是常数。因此“同 Gflops 下质量相当”这句话在图像分辨率区间内成立，一旦外推到长视频或高分辨率，同 Gflops 的两套配置可能对应完全不同的显存峰值与带宽需求。读论文表格时，先确认每个点的 L 与 patch 尺寸，再看 Gflops，否则会把一条被压平的曲线误当成线性可外推的容量规划依据。</p>\n<p>具体机制上，patchify 的线性投影把 H×W 的潜特征切成 (H/p)×(W/p) 个 token，L 与 p² 成反比。把 p 从 2 调到 4，L 降为四分之一，注意力矩阵元素数降为十六分之一，但 MLP 的参数量与每 token 计算量上升。这就是为什么消融里“patch 大小与宽度对 Gflops—质量关系影响显著”：两者在同一个 Gflops 标量下走的是不同的显存—带宽轨迹。推理系统代价的直接体现是：同一张卡上，p=2 的配置可能因注意力激活峰值而只能跑 batch=1，p=4 的配置能跑 batch=4，但后者单请求的 MLP 权重读取带宽更高。吞吐与延迟的权衡点因此随 patch 尺寸移动，不能只看 Gflops 对齐。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-46\">四十六 · 硬件档位与“未给出”的边界</h3>\n<p>论文没有给出硬件档位、并行拓扑、量化方案与批调度数据，这一点在深读时必须被显式标注为口径缺口，而不是用推测填补。对本卷读者而言，这意味着论文里的质量—Gflops 曲线只能回答“骨干规模怎么选”，不能回答“在 B200 单卡还是 GB200 NVL72 机柜上跑多少并发”。Blackwell 上的推理容量规划需要另行测量三件事：单步注意力激活峰值随 L 与 batch 的增长曲线、权重读取在 NVFP4/FP8 下的实际带宽占用、以及解码阶段 VAE 的显存峰值。论文的贡献是把骨干变成可按 Transformer 规则度量的对象，而不是给出部署参数表。</p>\n<p>一个可操作的换算思路：给定目标分辨率与 patch 尺寸算出 L，按 <span class=\"formula\">$$M_{\\text{attn}}\\approx b\\cdot h\\cdot L^2\\cdot \\text{bytes per element}$$</span> 估算注意力激活（b 为批大小、h 为头数），再与单卡显存上限比较得出 batch 上限；MLP 激活按 b·L·d 线性估算。这套估算不需要论文提供硬件数字，但需要读者自己测 k 的有效值。论文明确未涉及 NVFP4/FP8 量化、KV 缓存复用与分离式预填/解码，因此任何“DiT 在 Blackwell 上量化后吞吐提升多少”的说法都不能挂在这篇论文名下。条件注入经 adaLN-Zero 产生逐块 scale/shift，不增加 token，推理图与无条件路径基本一致——这一点对图捕获与算子融合有利，但它不改变上述显存估算的量级。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-47\">四十七 · batch、并发与步数三者的耦合口径</h3>\n<p>采样推理是固定步数循环，每步重复 patchify、N 层 Transformer 前向、unpatchify。步数增加时激活显存与带宽线性累积，这是“线性”的部分；批处理摊薄权重读取，这是吞吐的利好；但注意力激活随批大小线性上升，这是显存的利空。三者耦合的结果是：并发数不能独立于步数与分辨率设定。工程上常见的错误口径是“按图像分辨率定好 batch 后直接用于视频分块推理”，此时 L 因帧数与分块策略变化，注意力激活的平方项把显存峰值推高到超出预期。</p>\n<p>伪代码层面的调度约束可以写成：对每个候选 batch 值，检查 <span class=\"formula\">$$b\\cdot (c_1 L^2 + c_2 L d) \\le M_{\\text{free}}$$</span> 取满足不等式的最大 b，再用实测的单步时间乘以步数得到端到端延迟估计。这里的 c₁、c₂ 依赖精度与实现，必须实测。指标口径上，扩散采样没有自回归的 TTFT/TPOT 语义：首步延迟包含条件编码与首次权重加载，后续步是稳定的单步时间；因此报告“吞吐”时应明确是每秒完成的采样请求数还是每秒去噪步数，两者相差一个步数因子。论文未给出 SLO 吞吐数据，任何把 DiT 的 Gflops 直接换算成 QPS 的做法都缺少中间测量环节。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-48\">四十八 · 哪些提升不可比：四条判定线</h3>\n<p>读扩散推理的加速结果时，四条线决定数字能否放在一起比。第一条是 token 序列口径：分辨率、patch 尺寸、帧数、分块重叠策略任一不同，L 就不同，注意力代价不同。第二条是步数与采样器：步数不同则总计算量不同，少步采样与标准步数的吞吐数字不可直接并列。第三条是精度与量化路径：论文未涉及 NVFP4/FP8，若一方用 FP16 另一方用 FP8，显存与带宽占用不可比，且注意力激活量化需先验证数值稳定性，否则质量下降会污染“加速”结论。第四条是硬件与并行拓扑：单卡、双卡 2-SM MMA、机柜级 NVLink 5 域下的通信开销完全不同，论文未给出拓扑，跨拓扑比较无效。</p>\n<p>具体例子：某配置把 patch 从 2 改到 4，Gflops 标量相近，但 L 降为四分之一，注意力激活降为十六分之一，于是 batch 可以放大，吞吐上升。这个提升来自显存口径的改变，而不是骨干计算效率的提升；把它与另一篇在相同 patch 下做缓存复用的加速结果并列，会得出错误的排序。同理，把 DiT 的 Gflops 缩放结论外推到长视频推理、忽略 token 平方注意力带来的显存非线性，是论文局限里点明的失败模式之一。判定线的用途不是否定数字，而是给每个数字标注它成立的口径边界。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-49\">四十九 · 从论文表格到容量规划的最小读法</h3>\n<p>面对论文的结果表，最小读法是三步：先锁定 L（由分辨率与 patch 决定），再锁定 Gflops 档位对应的 (N, d, p) 组合，最后检查该组合的注意力激活估算是否落在目标硬件的显存预算内。论文报告 DiT 在相同或更低 Gflops 下取得与 U-Net 相当或更好的质量，并给出随 Gflops 增加质量提升的缩放趋势，具体 FID 数值未给出——这意味着质量侧的读法是定性的趋势判断，不是可插值的曲线。容量规划真正需要的是把趋势翻译成“给定显存预算下可用的最大 L 与 batch”，而这依赖读者自测的 c₁、c₂ 与精度选择。</p>\n<p>工程判断落在一点上：DiT 给 Blackwell 部署留下的最有价值遗产不是某条曲线，而是骨干形态的可度量性——算子序列、注意力形状、激活规模都能按 Transformer 规则估算，从而使 NVFP4/FP8 量化、跨步激活缓存复用、序列维并行切分有了统一的分析对象。但论文本身没有回答量化稳定性、缓存命中率与分离式部署的收益，这些必须在真实负载上测。把 Gflops 当横轴做容量规划时，务必同时把 L² 的显存项写在旁边；两条轴一起看，缩放结论才不会在长序列场景下失效。</p>\n\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-50\">五十 · 当缩放曲线撞上注意力平方：DiT 基准口径的失效边界</h3>\n<p>把 DiT 的 Gflops 缩放结论搬进推理容量规划，最容易犯的错是把 <span class=\"formula\">$$\\mathrm{Gflops}\\approx k\\cdot N\\cdot d^2\\cdot L$$</span> 当成显存的代理变量。这条式子只刻画了权重与 MLP 的乘加量，随宽度 d 平方、深度 N 线性增长；而推理显存的主项是注意力激活，随 token 数 T 平方增长、随批大小 B 线性增长，与 d 的关系反而弱。两者在图像分辨率下大致同向，一旦切到长视频或高分辨率分块，T 先爆，Gflops 还稳稳落在预算内，显存峰值却已越线。因此读 DiT 的缩放数据时必须把口径拆成两条轴：一条是 Gflops 决定的“算力档位”，用于选宽度/深度/patch；另一条是 T²·B 决定的“激活档位”，用于定单卡显存上限与批大小。论文给出的质量随 Gflops 提升的趋势只在第二条轴不成为约束时成立，越过这个边界，曲线不再可读。</p>\n<p>具体机制上，每步去噪循环固定执行 patchify→N 层全局自注意力＋MLP→unpatchify，条件经 adaLN-Zero 生成逐块 scale/shift，不额外增加 token，因此推理图与无条件路径同构——这一点让算子融合与图捕获变简单，但也意味着没有任何结构性的稀疏性可以利用：注意力矩阵是稠密的 T×T。设单步注意力激活为 <span class=\"formula\">$$M_{\\text{attn}}\\approx B\\cdot H\\cdot T^2\\cdot s$$</span>（H 为头数，s 为每元素字节数），则 S 步采样的激活带宽代价近似 <span class=\"formula\">$$W\\approx S\\cdot B\\cdot H\\cdot T^2\\cdot s\\cdot \\alpha$$</span>，α 为注意力矩阵读写次数系数。以图像 256 分辨率、patch 2 为例，T 在数千量级，B 取 8 尚可；换成视频分块后 T 上升一个数量级，同样的 B 与 s 会让 M_attn 涨两个数量级，此时唯一可行的手段是降 B、切分块并加重叠，代价是权重读取无法摊薄、吞吐下滑。这就是批处理在 DiT 上的真实权衡：摊薄的是权重带宽，抬高的是激活显存，两者方向相反。</p>\n<p>不可比的提升主要来自三类口径错配。其一是分辨率与 patch 尺寸不同：patch 从 2 改到 4，T 降为四分之一，注意力激活降一个数量级，Gflops 也降，但生成质量的可比性已被破坏，任何“更快”都混入了任务难度变化。其二是步数不同：采样步数 S 线性放大激活与带宽累积，少步采样器与标准 DDPM 步数下的 TTFT/TPOT 不可直接对比。其三是精度与部署形态不同：论文未涉及 NVFP4/FP8 量化、KV/激活缓存复用与分离式预填/解码，因此任何带量化的吞吐数字都不能挂到 DiT 原始缩放结论上；对注意力激活做 FP8 前必须先验证数值稳定性，否则采样质量下降会被误读为“模型不行”。工程上建议的读表口径是固定 (分辨率, patch, 步数, 精度) 四元组后再比吞吐，并把 TTFT 拆成条件编码、首步前向与 VAE 解码三段分别记账，因为解码阶段的显存峰值往往与去噪循环峰值不同源。</p>\n<table class=\"mini\"><thead><tr><th>口径变量</th><th>对 Gflops 的影响</th><th>对激活显存/带宽的影响</th><th>可比性判断</th></tr></thead><tbody><tr><td>patch 尺寸减半</td><td>约升 4×</td><td>T² 约升 16×</td><td>不可比，任务难度已变</td></tr><tr><td>批大小 B 翻倍</td><td>约升 2×</td><td>线性升 2×</td><td>可比的吞吐口径，需报显存峰值</td></tr><tr><td>采样步数 S 翻倍</td><td>线性升 2×</td><td>线性累积 2×</td><td>不可比，须注明采样器</td></tr><tr><td>注意力激活 FP8</td><td>基本不变</td><td>带宽约减半</td><td>需附数值稳定性验证</td></tr></tbody></table>\n<p>失效条件可以收敛成一句工程判断：当 <span class=\"formula\">$$B\\cdot H\\cdot T^2\\cdot s$$</span> 逼近单卡可用显存的高水位时，DiT 的 Gflops 缩放曲线对容量规划失去指导意义，此时应切换到以 token 数为自变量的显存估算，并把分块重叠、批大小与步数联合求解，而不是继续按 Gflops 档位加宽模型。反过来，只有当 T 被 patch 尺寸与分辨率压在低位、B 仍有余量时，论文的缩放趋势才是可信的规划依据；这也是 DiT 在 Blackwell 上做精度量化与并行切分时，必须先固定 token 序列形状再谈吞吐的原因。</p>\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-51\">五十一 · 从图像DiT迁到视频DiT：序列维度的代价重估</h3>\n<p>把DiT的图像推理方案搬到视频，最先失效的不是算子，而是容量估算的口径。图像DiT的token数由分辨率与patch尺寸决定，一次前向的注意力矩阵是 <span class=\"inline-math\">T×T</span>；视频DiT在同样的patch尺寸下把时间维展开，token数变成 <span class=\"inline-math\">T_f·T_h·T_w</span>，注意力矩阵规模按平方增长。论文给出的Gflops近似式 <span class=\"inline-math\">Gflops≈k·N·d²·L</span> 只对宽度、深度、层数线性，对token数并不显式；一旦序列长度翻倍，MLP部分近似线性翻倍，而注意力部分近似四倍。这意味着按图像DiT标定出的“每Gflops对应多少显存”在视频上系统性偏低。</p>\n<div class=\"formula\">$$\\text{AttnBytes}\\approx B\\cdot H\\cdot T^2\\cdot s,\\qquad \\text{MLPBytes}\\approx B\\cdot T\\cdot d^2\\cdot s$$</div>\n<p>其中 <span class=\"inline-math\">B</span> 为批大小、<span class=\"inline-math\">H</span> 为头数、<span class=\"inline-math\">s</span> 为每元素字节数。工程判断是：迁移时先把 <span class=\"inline-math\">T</span> 单独拎出来做敏感度扫描，而不是沿用图像档位的批大小。具体例子：同一patch尺寸下，把帧数从单帧扩到多帧，token数按帧数倍增长，注意力激活按帧数平方增长，此时若仍按图像DiT的批大小配置，显存峰值会在采样循环的中段而非首步就击穿预算——因为激活随步数线性累积，峰值出现在循环内而非单步。</p>\n<p>代价落点明确：视频DiT的瓶颈从“权重读取”转向“注意力激活带宽”。权重在批处理下被摊薄，而注意力矩阵每步都要写回与再读，带宽压力随 <span class=\"inline-math\">T²</span> 上升。迁移的第一项改动是把批大小与序列长度联合规划，长序列场景倾向小批或分块，而不是把图像DiT的批大小直接乘上去。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-52\">五十二 · 迁到非Transformer骨干：可分析性的丧失</h3>\n<p>DiT的真正遗产不是某个算子，而是“骨干可按Transformer规则度量”这一属性：算子序列固定、注意力形状可写、激活规模可估。把这套推理方案迁回U-Net或迁到混合骨干（卷积下采样＋Transformer中段），首先丢掉的是统一度量。U-Net的下采样堆叠与跳连使激活规模依赖特征图分辨率与通道数的组合，跳连还会在解码路径上保留多份中间激活，显存峰值不再由单一token序列决定。</p>\n<p>伪代码层面的差异在于规划入口：DiT可以写 <span class=\"inline-math\">plan(B, T, N, d)</span> 直接估出每步激活；U-Net需要 <span class=\"inline-math\">plan(B, res_list, ch_list, skip_flags)</span>，其中跳连开关改变峰值位置。工程判断：迁到非Transformer骨干时，精度量化与缓存复用的收益要重新标定，因为可融合的算子边界变了——卷积与归一化的融合规则与注意力的融合规则不同，NVFP4/FP8的缩放因子粒度也随之改变。具体例子：在混合骨干中，中段注意力的token数可能远小于图像DiT的全序列，量化注意力的收益下降，而卷积路径的权重量化成为主要收益来源，这与DiT的优化顺序相反。</p>\n<p>代价是诊断成本：DiT的失败模式可以归因到token平方或MLP带宽两类，混合骨干的失败模式分散在跳连显存、卷积融合与注意力三处，监控点需要增加。迁移不是把DiT的调参表照搬，而是重建一张按算子类型分列的显存与带宽账单。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-53\">五十三 · 迁到自回归与流式生成：缓存语义不成立</h3>\n<p>扩散采样的固定步数循环里没有自回归KV，缓存复用的对象是跨步激活与条件嵌入。迁到自回归视频生成或流式生成时，KV cache成为一等公民，而DiT方案里“每步重算全序列”的假设直接失效。论文明确未涉及KV缓存复用，因此把DiT的推理图迁到自回归形态需要重写调度层：连续批处理要按序列增长管理KV块，而非按固定token数分配激活。</p>\n<p>公式层面，自回归的每步代价是 <span class=\"inline-math\">O(T·d² + T·d·T_kv)</span>，其中 <span class=\"inline-math\">T_kv</span> 为已缓存长度；扩散DiT的每步代价是 <span class=\"inline-math\">O(T²·d + T·d²)</span>。两者对批大小的敏感度不同：自回归的KV随批线性增长且跨步驻留，扩散的激活随批线性增长但步内释放。工程判断是：把DiT的批调度策略迁到自回归形态会导致KV显存超配，因为扩散方案按“步内峰值”规划，而自回归需要按“跨步累积峰值”规划。具体例子：同一张卡上，扩散DiT可以在大步数下维持中等批，自回归形态在相同批下KV会在数十步后占满剩余显存，必须引入KV分页或驱逐。</p>\n<p>代价落在调度器复杂度与显存碎片：扩散的激活是规则的、可预测的，自回归的KV是增长的、长度不齐的，连续批处理的块管理开销上升。迁移时不能复用扩散的批大小标定，而要按KV块上限反推批上限。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-54\">五十四 · 精度迁移的边界：注意力数值稳定性</h3>\n<p>DiT论文未给出量化实验，因此把NVFP4/FP8迁到DiT注意力属于“需另行测量”的范畴，而不是可直接套用的配方。边界在于：MLP与线性投影的权重量化对采样质量的影响相对可控，注意力矩阵的softmax输入量化则敏感——注意力分数在去噪早期与晚期分布不同，早期分数动态范围大，低精度累加容易改变softmax的排序，进而改变采样轨迹。</p>\n<p>伪代码思路是分层量化策略：权重统一走低精度，激活按算子分档，注意力分数在累加时保留较高精度、在softmax后再降精度。代价是吞吐：混合精度路径引入类型转换与缩放因子读取，带宽收益被部分抵消；在Blackwell上tcgen05的MMA形状对混合精度有约束，转换点若落在MMA边界之外会增加额外搬运。具体例子：对注意力激活整体做FP8量化而未验证稳定性时，采样质量下降往往表现为纹理细节退化而非整体崩坏，诊断上容易被误判为步数不足。工程判断是：量化迁移必须先做小规模采样对比，把注意力分数单独列为受控变量，而不是把整网量化当作一个开关。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-55\">五十五 · 规模上限：token平方与步数线性的双重夹击</h3>\n<p>DiT的规模上限由两条曲线夹定：注意力激活随token数平方上升，激活显存与带宽随步数线性累积。两条曲线相乘，决定了单卡可承载的“分辨率×帧数×步数×批大小”组合的上界。论文的Gflops缩放趋势描述的是质量随计算量提升，但计算量提升的路径有两条——加宽加深（线性增Gflops）与加长序列（平方增注意力）——后者在推理上更快触顶。</p>\n<div class=\"formula\">$$\\text{Feasible}(B,T,S)\\iff B\\cdot T^2\\cdot S\\cdot s\\le M_{\\text{free}}$$</div>\n<p>其中 <span class=\"inline-math\">S</span> 为采样步数、<span class=\"inline-math\">M_free</span> 为扣除权重与解码峰值后的可用显存。工程判断是：规模上限不在模型参数，而在 <span class=\"inline-math\">T²·S</span> 这一乘积。具体例子：提高分辨率以提升质量时，token数上升使可行步数下降，若采样器需要较多步数才能收敛，则分辨率提升与步数需求互相挤压，最终可行域收缩到小批甚至单样本。此时分块与重叠策略成为唯一出路，但重叠区带来重复计算，吞吐按重叠比例折损。</p>\n<p>迁移到长视频时，这条上界比图像更紧：帧数增加同时抬高 <span class=\"inline-math\">T</span> 与 <span class=\"inline-math\">S</span> 的有效需求（长视频通常需要更多步维持时序一致），可行域按两个维度同时收缩。判断而非口号：DiT方案的可扩展性在图像域成立，在长视频域需要分块推理与跨块条件传递作为前置条件，否则规模上限由显存而非质量需求决定。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-56\">五十六 · 迁移判断清单：什么能搬、什么必须重做</h3>\n<p>把DiT推理方案迁到新模型或新领域，可按三条线判断。可搬的是：以token序列为单位的容量估算框架、adaLN-Zero这类不增加token的条件注入方式（推理图与无条件路径一致，迁移时不需要改图结构）、以及按Gflops分档做容量规划的方法论。必须重做的是：批大小标定（序列长度语义变了）、缓存策略（自回归形态下KV语义不同）、量化配方（注意力稳定性需重测）。不适用的是：把图像DiT的Gflops-质量缩放结论直接外推到长视频，因为该结论的自变量不含token平方项。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>可直接复用</th><th>必须重做</th><th>主要代价</th></tr></thead><tbody><tr><td>视频DiT</td><td>token估算框架、条件注入</td><td>批大小、分块重叠策略</td><td>注意力激活带宽随T²上升</td></tr><tr><td>混合/U-Net骨干</td><td>量化方法论</td><td>激活账单、融合边界</td><td>跳连显存峰值、诊断点增多</td></tr><tr><td>自回归/流式</td><td>算子精度策略</td><td>调度层、KV块管理</td><td>KV跨步驻留、显存碎片</td></tr><tr><td>低精度部署</td><td>权重低精度</td><td>注意力分数精度分档</td><td>转换开销、稳定性验证</td></tr></tbody></table>\n<p>最后落在具体机制上：迁移时先把目标形态的每步代价写成关于 <span class=\"inline-math\">(B, T, S)</span> 的显式函数，再决定哪些参数沿用DiT档位、哪些按新形态重标。若函数中 <span class=\"inline-math\">T</span> 以平方出现且 <span class=\"inline-math\">S</span> 不可压缩，则该形态的规模上限由分块策略而非模型规模决定——这是迁移判断的硬边界，不是调参能绕过的。</p>\n\n<h3 id=\"paper-scalable-diffusion-models-with-trans-2022-sec-57\">五十七 · 迁移到长视频与高分辨率时的失效边界</h3>\n<p>把DiT这套方案迁到图像之外的领域，第一道坎不是模型结构而是序列长度。图像侧token数由分辨率与patch尺寸决定，分辨率翻倍、patch不变，token数按四倍增长，注意力矩阵按十六倍膨胀；视频再叠加时间维，帧数直接乘进序列长度。此时论文给出的Gflops缩放关系$$\\mathrm{Gflops}\\approx k\\cdot N\\cdot d^2\\cdot L$$仍然成立，但它只刻画了权重与MLP的线性项，掩盖了注意力激活的平方项。工程上必须把每步激活峰值单独建模为$S^2\\cdot B\\cdot H$量级（$S$为token数、$B$为批、$H$为头数），否则按图像分辨率标定的批大小迁到视频分块会直接击穿显存。代价是明确的：长序列下要么把批压到1、要么引入带重叠的分块推理，重叠区带来的重复计算会吃掉分块省下的显存收益，吞吐随重叠比例线性下降。</p>\n<p>第二个失效条件是数值精度。论文未涉及NVFP4/FP8量化，而全局注意力的softmax对激活量化极敏感——把FP8直接套到注意力矩阵上，缩放因子按块统计时，长序列中稀疏的大值会拉偏整块的动态范围，采样质量下降表现为纹理退化而非直接崩溃，很难在离线指标上第一时间发现。可迁移的做法是权重走NVFP4/FP8、注意力激活保持BF16或做逐头缩放，把量化收益限制在MLP与投影层；代价是权重带宽节省被激活带宽抵消一部分，端到端加速比低于纯Transformer语言模型的经验值。</p>\n<p>第三个边界是缓存语义。扩散采样没有自回归KV，跨步复用只能针对条件嵌入与不变的中低层激活，而adaLN-Zero产生的逐块scale/shift每步随$t$变化，无法跨步缓存。这意味着分离式预填/解码那套把预填与解码拆到不同资源池的收益在DiT上大幅缩水：每步都是一次完整前向，没有可复用的长上下文。判断标准很直接——若单步前向的MLP权重读取时间占比高于注意力计算，批处理摊薄权重读取仍然划算；一旦序列长到注意力主导，增大批只会线性推高激活显存，此时应转向序列并行切分，并接受注意力矩阵切分带来的All-to-All通信代价。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>可直接沿用</th><th>必须改造</th></tr></thead><tbody><tr><td>高分辨率图像</td><td>patchify、adaLN-Zero、Gflops容量规划</td><td>批大小按$S^2$重估，分块重叠策略</td></tr><tr><td>长视频</td><td>Transformer块切分、权重量化</td><td>时空注意力分解、激活量化逐头缩放</td></tr><tr><td>分离式部署</td><td>并行切分拓扑</td><td>放弃KV复用假设，按步重算</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Scalable Diffusion Models </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">with Transfor…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2022 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Scalable Diffusion Mode… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>ImageNet类别条件生成（分辨率未给出）</td></tr><tr><td>基线</td><td>U-Net扩散骨干（同Gflops档位对比）</td></tr><tr><td>主要结果</td><td>论文报告DiT在相同或更低Gflops下取得与U-Net骨干相当或更好的生…</td></tr><tr><td>消融</td><td>对patch尺寸、模型宽度与深度、adaLN-Zero条件注入方式做了消融…</td></tr><tr><td>局限</td><td>全局注意力使token数增大时激活显存与带宽快速上升；高分辨率与长视频场景…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-scalable-diffusion-models-with-trans-2022 · 共 9 个片段</p>\n";break;}}})();
